INSERT INTO `raw_data` VALUES (1,2010,1013,NULL,4630492758,100,'ModemManager.service','ModemManager','[Unit]\nDescription=Modem Manager\nAfter=polkit.service\nRequires=polkit.service\nConditionVirtualization=!container\n\n[Service]\nType=dbus\nBusName=org.freedesktop.ModemManager1\nExecStart=/usr/sbin/ModemManager\nStandardError=null\nRestart=on-abort\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN\nProtectSystem=true\nProtectHome=true\nPrivateTmp=true\nRestrictAddressFamilies=AF_NETLINK AF_UNIX AF_QIPCRTR\nNoNewPrivileges=true\nUser=root\n\n[Install]\nWantedBy=multi-user.target\nAlias=dbus-org.freedesktop.ModemManager1.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:55','2026-10-17 13:49:55'),(2,2011,1013,NULL,4630492758,101,'NetworkManager-wait-online.service','NetworkManager-wait-online','[Unit]\nDescription=Network Manager Wait Online\nDocumentation=man:nm-online(1)\nRequires=NetworkManager.service\nAfter=NetworkManager.service\nBefore=network-online.target\n\n[Service]\n# `nm-online -s` waits until the point when NetworkManager logs\n# \"startup complete\". That is when startup actions are settled and\n# devices and profiles reached a conclusive activated or deactivated\n# state. It depends on which profiles are configured to autoconnect and\n# also depends on profile settings like ipv4.may-fail/ipv6.may-fail,\n# which affect when a profile is considered fully activated.\n# Check NetworkManager logs to find out why wait-online takes a certain\n# time.\n\nType=oneshot\nExecStart=/usr/bin/nm-online -s -q\nRemainAfterExit=yes\n\n# Set $NM_ONLINE_TIMEOUT variable for timeout in seconds.\n# Edit with `systemctl edit NetworkManager-wait-online`.\n#\n# Note, this timeout should commonly not be reached. If your boot\n# gets delayed too long, then the solution is usually not to decrease\n# the timeout, but to fix your setup so that the connected state\n# gets reached earlier.\nEnvironment=NM_ONLINE_TIMEOUT=60\n\n[Install]\nWantedBy=network-online.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:55','2026-10-17 13:49:55'),(3,2012,1013,NULL,4630492758,102,'NetworkManager.service','NetworkManager','[Unit]\nDescription=Network Manager\nDocumentation=man:NetworkManager(8)\nWants=network.target\nAfter=network-pre.target dbus.service\nBefore=network.target \n\n[Service]\nType=dbus\nBusName=org.freedesktop.NetworkManager\nExecReload=/usr/bin/busctl call org.freedesktop.NetworkManager /org/freedesktop/NetworkManager org.freedesktop.NetworkManager Reload u 0\n#ExecReload=/bin/kill -HUP $MAINPID\nExecStart=/usr/sbin/NetworkManager --no-daemon\nRestart=on-failure\n# NM doesn\'t want systemd to kill its children for it\nKillMode=process\n\n# CAP_DAC_OVERRIDE: required to open /run/openvswitch/db.sock socket.\nCapabilityBoundingSet=CAP_NET_ADMIN CAP_DAC_OVERRIDE CAP_NET_RAW CAP_NET_BIND_SERVICE CAP_SETGID CAP_SETUID CAP_SYS_MODULE CAP_AUDIT_WRITE CAP_KILL CAP_SYS_CHROOT\n\nProtectSystem=true\nProtectHome=read-only\n\n# We require file descriptors for DHCP etc. When activating many interfaces,\n# the default limit of 1024 is easily reached.\nLimitNOFILE=65536\n\n[Install]\nWantedBy=multi-user.target\nAlso=NetworkManager-dispatcher.service\n\n# We want to enable NetworkManager-wait-online.service whenever this service\n# is enabled. NetworkManager-wait-online.service has\n# WantedBy=network-online.target, so enabling it only has an effect if\n# network-online.target itself is enabled or pulled in by some other unit.\nAlso=NetworkManager-wait-online.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:55','2026-10-17 13:49:55'),(4,2013,1013,NULL,4630492758,103,'alsa-restore.service','alsa-restore','#\n# Note that two different ALSA card state management schemes exist and they\n# can be switched using a file exist check - /etc/alsa/state-daemon.conf .\n#\n\n[Unit]\nDescription=Save/Restore Sound Card State\nDocumentation=man:alsactl(1)\nConditionPathExists=!/etc/alsa/state-daemon.conf\nConditionPathExistsGlob=/dev/snd/control*\nAfter=alsa-state.service\n\n[Service]\nType=oneshot\nRemainAfterExit=true\nExecStart=-/usr/sbin/alsactl -E HOME=/run/alsa -E XDG_RUNTIME_DIR=/run/alsa/runtime restore\nExecStop=-/usr/sbin/alsactl -E HOME=/run/alsa -E XDG_RUNTIME_DIR=/run/alsa/runtime store\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:56','2026-10-17 13:49:56'),(5,2014,1013,NULL,4630492758,104,'avahi-daemon.service','avahi-daemon','# This file is part of avahi.\n#\n# avahi is free software; you can redistribute it and/or modify it\n# under the terms of the GNU Lesser General Public License as\n# published by the Free Software Foundation; either version 2 of the\n# License, or (at your option) any later version.\n#\n# avahi is distributed in the hope that it will be useful, but WITHOUT\n# ANY WARRANTY; without even the implied warranty of MERCHANTABILITY\n# or FITNESS FOR A PARTICULAR PURPOSE. See the GNU General Public\n# License for more details.\n#\n# You should have received a copy of the GNU Lesser General Public\n# License along with avahi; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place, Suite 330, Boston, MA 02111-1307\n# USA.\n\n[Unit]\nDescription=Avahi mDNS/DNS-SD Stack\nRequires=avahi-daemon.socket\n\n[Service]\nType=dbus\nBusName=org.freedesktop.Avahi\nExecStart=/usr/sbin/avahi-daemon -s\nExecReload=/usr/sbin/avahi-daemon -r\nNotifyAccess=main\n\n[Install]\nWantedBy=multi-user.target\nAlso=avahi-daemon.socket\nAlias=dbus-org.freedesktop.Avahi.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:56','2026-10-17 13:49:56'),(6,2015,1013,NULL,4630492758,105,'bluetooth.service','bluetooth','[Unit]\nDescription=Bluetooth service\nDocumentation=man:bluetoothd(8)\nConditionPathIsDirectory=/sys/class/bluetooth\n\n[Service]\nType=dbus\nBusName=org.bluez\nExecStart=/usr/libexec/bluetooth/bluetoothd\nNotifyAccess=main\n#WatchdogSec=10\n#Restart=on-failure\nCapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE\nLimitNPROC=1\n\n# Filesystem lockdown\nProtectHome=true\nProtectSystem=strict\nPrivateTmp=true\nProtectKernelTunables=true\nProtectControlGroups=true\nStateDirectory=bluetooth\nStateDirectoryMode=0700\nConfigurationDirectory=bluetooth\nConfigurationDirectoryMode=0555\n\n# Execute Mappings\nMemoryDenyWriteExecute=true\n\n# Privilege escalation\nNoNewPrivileges=true\n\n# Real-time\nRestrictRealtime=true\n\n[Install]\nWantedBy=bluetooth.target\nAlias=dbus-org.bluez.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:56','2026-10-17 13:49:56'),(7,2016,1013,NULL,4630492758,106,'console-setup.service','console-setup','[Unit]\nDescription=Set console font and keymap\nDefaultDependencies=no\nAfter=console-screen.service kbd.service local-fs.target\nBefore=display-manager.service\nRequiresMountsFor=/usr\nConditionPathExists=/bin/setupcon\n\n[Service]\nType=oneshot\nExecStart=/lib/console-setup/console-setup.sh\nRemainAfterExit=yes\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:57','2026-10-17 13:49:57'),(8,2017,1013,NULL,4630492758,107,'containerd.service','containerd','# Copyright The containerd Authors.\n#\n# Licensed under the Apache License, Version 2.0 (the \"License\");\n# you may not use this file except in compliance with the License.\n# You may obtain a copy of the License at\n#\n#     http://www.apache.org/licenses/LICENSE-2.0\n#\n# Unless required by applicable law or agreed to in writing, software\n# distributed under the License is distributed on an \"AS IS\" BASIS,\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n# See the License for the specific language governing permissions and\n# limitations under the License.\n\n[Unit]\nDescription=containerd container runtime\nDocumentation=https://containerd.io\nAfter=network.target local-fs.target\n\n[Service]\nExecStartPre=-/sbin/modprobe overlay\nExecStart=/usr/bin/containerd\n\nType=notify\nDelegate=yes\nKillMode=process\nRestart=always\nRestartSec=5\n# Having non-zero Limit*s causes performance problems due to accounting overhead\n# in the kernel. We recommend using cgroups to do container-local accounting.\nLimitNPROC=infinity\nLimitCORE=infinity\nLimitNOFILE=infinity\n# Comment TasksMax if your systemd version does not supports it.\n# Only systemd 226 and above support this version.\nTasksMax=infinity\nOOMScoreAdjust=-999\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:57','2026-10-17 13:49:57'),(9,2018,1013,NULL,4630492758,108,'cron.service','cron','[Unit]\nDescription=Regular background program processing daemon\nDocumentation=man:cron(8)\nAfter=remote-fs.target nss-user-lookup.target\n\n[Service]\nEnvironmentFile=-/etc/default/cron\nExecStart=/usr/sbin/cron -f $EXTRA_OPTS\nIgnoreSIGPIPE=false\nKillMode=process\nRestart=on-failure\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:57','2026-10-17 13:49:57'),(10,2019,1013,NULL,4630492758,109,'dbus.service','dbus','[Unit]\nDescription=D-Bus System Message Bus\nDocumentation=man:dbus-daemon(1)\nRequires=dbus.socket\n\n[Service]\nType=notify\nNotifyAccess=main\nExecStart=/usr/bin/dbus-daemon --system --address=systemd: --nofork --nopidfile --systemd-activation --syslog-only\nExecReload=/usr/bin/dbus-send --print-reply --system --type=method_call --dest=org.freedesktop.DBus / org.freedesktop.DBus.ReloadConfig\nOOMScoreAdjust=-900\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:58','2026-10-17 13:49:58'),(11,2020,1013,NULL,4630492758,110,'docker.service','docker','[Unit]\nDescription=Docker Application Container Engine\nDocumentation=https://docs.docker.com\nAfter=network-online.target docker.socket firewalld.service containerd.service\nWants=network-online.target containerd.service\nRequires=docker.socket\n\n[Service]\nType=notify\n# the default is not to use systemd for cgroups because the delegate issues still\n# exists and systemd currently does not support the cgroup feature set required\n# for containers run by docker\nEnvironmentFile=-/etc/default/docker\nExecStart=/usr/sbin/dockerd -H fd:// --containerd=/run/containerd/containerd.sock $DOCKER_OPTS\nExecReload=/bin/kill -s HUP $MAINPID\nLimitNOFILE=1048576\n# Having non-zero Limit*s causes performance problems due to accounting overhead\n# in the kernel. We recommend using cgroups to do container-local accounting.\nLimitNPROC=infinity\nLimitCORE=infinity\n# Uncomment TasksMax if your systemd version supports it.\n# Only systemd 226 and above support this version.\nTasksMax=infinity\nTimeoutStartSec=0\n# set delegate yes so that systemd does not reset the cgroups of docker containers\nDelegate=yes\n# kill only the docker process, not all processes in the cgroup\nKillMode=process\n# restart the docker process if it exits prematurely\nRestart=on-failure\nStartLimitBurst=3\nStartLimitInterval=60s\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:58','2026-10-17 13:49:58'),(12,2021,1013,NULL,4630492758,111,'dphys-swapfile.service','dphys-swapfile','[Unit]\nDescription=dphys-swapfile - set up, mount/unmount, and delete a swap file\nDocumentation=man:dphys-swapfile(8)\n\n[Service]\nType=oneshot\nExecStart=/sbin/dphys-swapfile setup\nExecStart=/sbin/dphys-swapfile swapon\nExecStop=/sbin/dphys-swapfile swapoff\nRemainAfterExit=yes\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:59','2026-10-17 13:49:59'),(13,2022,1013,NULL,4630492758,112,'fake-hwclock.service','fake-hwclock','[Unit]\nDescription=Restore / save the current clock\nDocumentation=man:fake-hwclock(8)\nDefaultDependencies=no\nBefore=sysinit.target shutdown.target\nConflicts=shutdown.target\n\n[Service]\nEnvironmentFile=-/etc/default/fake-hwclock\nExecStart=/sbin/fake-hwclock load $FORCE\nExecStop=/sbin/fake-hwclock save\nType=oneshot\nRemainAfterExit=yes\n\n[Install]\nWantedBy=sysinit.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:59','2026-10-17 13:49:59'),(14,2023,1013,NULL,4630492758,113,'getty@.service','getty@tty1','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Getty on %I\nDocumentation=man:agetty(8) man:systemd-getty-generator(8)\nDocumentation=https://0pointer.de/blog/projects/serial-console.html\nAfter=systemd-user-sessions.service plymouth-quit-wait.service getty-pre.target\nAfter=rc-local.service\n\n# If additional gettys are spawned during boot then we should make\n# sure that this is synchronized before getty.target, even though\n# getty.target didn\'t actually pull it in.\nBefore=getty.target\nIgnoreOnIsolate=yes\n\n# IgnoreOnIsolate causes issues with sulogin, if someone isolates\n# rescue.target or starts rescue.service from multi-user.target or\n# graphical.target.\nConflicts=rescue.service\nBefore=rescue.service\n\n# On systems without virtual consoles, don\'t start any getty. Note\n# that serial gettys are covered by serial-getty@.service, not this\n# unit.\nConditionPathExists=/dev/tty0\n\n[Service]\n# the VT is cleared by TTYVTDisallocate\n# The \'-o\' option value tells agetty to replace \'login\' arguments with an\n# option to preserve environment (-p), followed by \'--\' for safety, and then\n# the entered username.\nExecStart=-/sbin/agetty -o \'-p -- \\\\u\' --noclear - $TERM\nType=idle\nRestart=always\nRestartSec=0\nUtmpIdentifier=%I\nStandardInput=tty\nStandardOutput=tty\nTTYPath=/dev/%I\nTTYReset=yes\nTTYVHangup=yes\nTTYVTDisallocate=yes\nIgnoreSIGPIPE=no\nSendSIGHUP=yes\n\n# Unset locale for the console getty since the console has problems\n# displaying some internationalized messages.\nUnsetEnvironment=LANG LANGUAGE LC_CTYPE LC_NUMERIC LC_TIME LC_COLLATE LC_MONETARY LC_MESSAGES LC_PAPER LC_NAME LC_ADDRESS LC_TELEPHONE LC_MEASUREMENT LC_IDENTIFICATION\n\n[Install]\nWantedBy=getty.target\nDefaultInstance=tty1\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:49:59','2026-10-17 13:49:59'),(15,2024,1013,NULL,4630492758,114,'keyboard-setup.service','keyboard-setup','[Unit]\nDescription=Set the console keyboard layout\nDefaultDependencies=no\nBefore=local-fs-pre.target\nWants=local-fs-pre.target\nConditionPathExists=/bin/setupcon\n\n[Service]\nType=oneshot\nExecStart=/lib/console-setup/keyboard-setup.sh\nRemainAfterExit=yes\n\n[Install]\nWantedBy=sysinit.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:00','2026-10-17 13:50:00'),(16,2025,1013,NULL,4630492758,115,'kmod-static-nodes.service','kmod-static-nodes','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create List of Static Device Nodes\nDefaultDependencies=no\nBefore=sysinit.target systemd-tmpfiles-setup-dev.service\nConditionCapability=CAP_SYS_MODULE\nConditionFileNotEmpty=/lib/modules/%v/modules.devname\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/bin/kmod static-nodes --format=tmpfiles --output=/run/tmpfiles.d/static-nodes.conf\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:00','2026-10-17 13:50:00'),(17,2026,1013,NULL,4630492758,116,'polkit.service','polkit','[Unit]\nDescription=Authorization Manager\nDocumentation=man:polkit(8)\n\n[Service]\nType=dbus\nBusName=org.freedesktop.PolicyKit1\nExecStart=/usr/lib/polkit-1/polkitd --no-debug\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:01','2026-10-17 13:50:01'),(18,2027,1013,NULL,4630492758,117,'rpc-statd-notify.service','rpc-statd-notify','[Unit]\nDescription=Notify NFS peers of a restart\nDefaultDependencies=no\nWants=network-online.target\nAfter=local-fs.target network-online.target nss-lookup.target\n\n# if we run an nfs server, it needs to be running before we\n# tell clients that it has restarted.\nAfter=nfs-server.service\n\nPartOf=nfs-utils.service\n\n[Service]\nType=forking\nExecStart=-/sbin/sm-notify\nRemainAfterExit=yes\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:01','2026-10-17 13:50:01'),(19,2028,1013,NULL,4630492758,118,'rpi-eeprom-update.service','rpi-eeprom-update','[Unit]\nDescription=Check for Raspberry Pi EEPROM updates\nAfter=boot-firmware.mount\n\n[Service]\nType=oneshot\nRemainAfterExit=true\nExecStart=/usr/bin/rpi-eeprom-update -s -a\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:01','2026-10-17 13:50:01'),(20,2029,1013,NULL,4630492758,119,'ssh.service','ssh','[Unit]\nDescription=OpenBSD Secure Shell server\nDocumentation=man:sshd(8) man:sshd_config(5)\nAfter=network.target auditd.service\nConditionPathExists=!/etc/ssh/sshd_not_to_be_run\n\n[Service]\nEnvironmentFile=-/etc/default/ssh\nExecStartPre=/usr/sbin/sshd -t\nExecStart=/usr/sbin/sshd -D $SSHD_OPTS\nExecReload=/usr/sbin/sshd -t\nExecReload=/bin/kill -HUP $MAINPID\nKillMode=process\nRestart=on-failure\nRestartPreventExitStatus=255\nType=notify\nRuntimeDirectory=sshd\nRuntimeDirectoryMode=0755\n\n[Install]\nWantedBy=multi-user.target\nAlias=sshd.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:02','2026-10-17 13:50:02'),(21,2030,1013,NULL,4630492758,120,'systemd-binfmt.service','systemd-binfmt','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Set Up Additional Binary Formats\nDocumentation=man:systemd-binfmt.service(8) man:binfmt.d(5)\nDocumentation=https://docs.kernel.org/admin-guide/binfmt-misc.html\nDocumentation=https://www.freedesktop.org/wiki/Software/systemd/APIFileSystems\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=proc-sys-fs-binfmt_misc.automount\nAfter=proc-sys-fs-binfmt_misc.mount\nAfter=local-fs.target\nBefore=sysinit.target shutdown.target\nConditionPathIsMountPoint=/proc/sys/fs/binfmt_misc\nConditionDirectoryNotEmpty=|/lib/binfmt.d\nConditionDirectoryNotEmpty=|/usr/lib/binfmt.d\nConditionDirectoryNotEmpty=|/usr/local/lib/binfmt.d\nConditionDirectoryNotEmpty=|/etc/binfmt.d\nConditionDirectoryNotEmpty=|/run/binfmt.d\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-binfmt\nExecStop=/lib/systemd/systemd-binfmt --unregister\nTimeoutSec=90s\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:02','2026-10-17 13:50:02'),(22,2031,1013,NULL,4630492758,121,'systemd-fsck@.service','systemd-fsck@dev-disk-by\\x2dpartuuid-75f44ebd\\x2d01','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=File System Check on %f\nDocumentation=man:systemd-fsck@.service(8)\nDefaultDependencies=no\nBindsTo=%i.device\nConflicts=shutdown.target\nWants=systemd-fsckd.socket\nAfter=%i.device systemd-fsck-root.service local-fs-pre.target systemd-fsckd.socket\nBefore=systemd-quotacheck.service shutdown.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-fsck %f\nTimeoutSec=0\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:02','2026-10-17 13:50:02'),(23,2032,1013,NULL,4630492758,122,'systemd-journal-flush.service','systemd-journal-flush','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Flush Journal to Persistent Storage\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\nDefaultDependencies=no\nWants=systemd-journald.service\nAfter=systemd-journald.service systemd-remount-fs.service\nBefore=systemd-tmpfiles-setup.service\nRequiresMountsFor=/var/log/journal\nConditionPathExists=!/etc/initrd-release\n\n[Service]\nExecStart=journalctl --flush\nExecStop=journalctl --smart-relinquish-var\nType=oneshot\nRemainAfterExit=yes\nTimeoutSec=90s\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:03','2026-10-17 13:50:03'),(24,2033,1013,NULL,4630492758,123,'systemd-journald.service','systemd-journald','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Journal Service\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\nDefaultDependencies=no\nRequires=systemd-journald.socket\nAfter=systemd-journald.socket systemd-journald-dev-log.socket systemd-journald-audit.socket syslog.socket\nBefore=sysinit.target\n\n# Mount and swap units need the journal socket units. If they were removed by\n# an isolate request the mount and swap units would be removed too, hence let\'s\n# exclude systemd-journald and its sockets from isolate requests.\nIgnoreOnIsolate=yes\n\n[Service]\nDeviceAllow=char-* rw\nExecStart=/lib/systemd/systemd-journald\nFileDescriptorStoreMax=4224\nIPAddressDeny=any\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nOOMScoreAdjust=-250\nProtectClock=yes\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/journal\nRuntimeDirectoryPreserve=yes\nSockets=systemd-journald.socket systemd-journald-dev-log.socket systemd-journald-audit.socket\nStandardOutput=null\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nType=notify\nWatchdogSec=3min\n\n# In case you\'re wondering why CAP_SYS_PTRACE is needed, access to\n# /proc/<pid>/exe requires this capability. Thus if this capability is missing\n# the _EXE=/OBJECT_EXE= fields will be missing from the journal entries.\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_DAC_OVERRIDE CAP_SYS_PTRACE CAP_SYSLOG CAP_AUDIT_CONTROL CAP_AUDIT_READ CAP_CHOWN CAP_DAC_READ_SEARCH CAP_FOWNER CAP_SETUID CAP_SETGID CAP_MAC_OVERRIDE\n\n# If there are many split up journal files we need a lot of fds to access them\n# all in parallel.\nLimitNOFILE=524288\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:03','2026-10-17 13:50:03'),(25,2034,1013,NULL,4630492758,124,'systemd-logind.service','systemd-logind','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Login Management\nDocumentation=man:sd-login(3)\nDocumentation=man:systemd-logind.service(8)\nDocumentation=man:logind.conf(5)\nDocumentation=man:org.freedesktop.login1(5)\n\nWants=user.slice modprobe@drm.service\nAfter=nss-user-lookup.target user.slice modprobe@drm.service\nConditionPathExists=|/lib/systemd/system/dbus.service\nConditionPathExists=|/lib/systemd/system/dbus-broker.service\n\n# Ask for the dbus socket.\nWants=dbus.socket\nAfter=dbus.socket\n\n[Service]\nBusName=org.freedesktop.login1\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_MAC_ADMIN CAP_AUDIT_CONTROL CAP_CHOWN CAP_DAC_READ_SEARCH CAP_DAC_OVERRIDE CAP_FOWNER CAP_SYS_TTY_CONFIG CAP_LINUX_IMMUTABLE\nDeviceAllow=block-* r\nDeviceAllow=char-/dev/console rw\nDeviceAllow=char-drm rw\nDeviceAllow=char-hvc rw\nDeviceAllow=char-input rw\nDeviceAllow=char-tty rw\nDeviceAllow=char-vcs rw\nExecStart=/lib/systemd/systemd-logind\nFileDescriptorStoreMax=512\nIPAddressDeny=any\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateTmp=yes\n# We don\'t use ProtectProc= since we need to look for usernames and tty for wall messages\nProtectClock=yes\nProtectControlGroups=yes\nProtectHome=yes\nProtectHostname=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectSystem=strict\nReadWritePaths=/etc /run\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/sessions systemd/seats systemd/users systemd/inhibit systemd/shutdown\nRuntimeDirectoryPreserve=yes\nStateDirectory=systemd/linger\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nWatchdogSec=3min\n\n# Increase the default a bit in order to allow many simultaneous logins since\n# we keep one fd open per session.\nLimitNOFILE=524288\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:03','2026-10-17 13:50:03'),(26,2035,1013,NULL,4630492758,125,'systemd-modules-load.service','systemd-modules-load','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Load Kernel Modules\nDocumentation=man:systemd-modules-load.service(8) man:modules-load.d(5)\nDefaultDependencies=no\nConflicts=shutdown.target\nBefore=sysinit.target shutdown.target\nConditionCapability=CAP_SYS_MODULE\nConditionDirectoryNotEmpty=|/lib/modules-load.d\nConditionDirectoryNotEmpty=|/usr/lib/modules-load.d\nConditionDirectoryNotEmpty=|/usr/local/lib/modules-load.d\nConditionDirectoryNotEmpty=|/etc/modules-load.d\nConditionDirectoryNotEmpty=|/run/modules-load.d\nConditionKernelCommandLine=|modules-load\nConditionKernelCommandLine=|modules_load\nConditionKernelCommandLine=|rd.modules-load\nConditionKernelCommandLine=|rd.modules_load\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-modules-load\nTimeoutSec=90s\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:04','2026-10-17 13:50:04'),(27,2036,1013,NULL,4630492758,126,'systemd-random-seed.service','systemd-random-seed','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Load/Save Random Seed\nDocumentation=man:systemd-random-seed.service(8) man:random(4)\nDefaultDependencies=no\nRequiresMountsFor=/var/lib/systemd/random-seed\nConflicts=shutdown.target\nAfter=systemd-remount-fs.service\nBefore=first-boot-complete.target shutdown.target\nWants=first-boot-complete.target\nConditionVirtualization=!container\nConditionPathExists=!/etc/initrd-release\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-random-seed load\nExecStop=/lib/systemd/systemd-random-seed save\n\n# This service waits until the kernel\'s entropy pool is initialized, and may be\n# used as ordering barrier for service that require an initialized entropy\n# pool. Since initialization can take a while on entropy-starved systems, let\'s\n# increase the timeout substantially here.\nTimeoutSec=10min\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:04','2026-10-17 13:50:04'),(28,2037,1013,NULL,4630492758,127,'systemd-remount-fs.service','systemd-remount-fs','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Remount Root and Kernel File Systems\nDocumentation=man:systemd-remount-fs.service(8)\nDocumentation=https://www.freedesktop.org/wiki/Software/systemd/APIFileSystems\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=systemd-fsck-root.service\nBefore=local-fs-pre.target local-fs.target shutdown.target\nWants=local-fs-pre.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-remount-fs\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:04','2026-10-17 13:50:04'),(29,2038,1013,NULL,4630492758,128,'systemd-sysctl.service','systemd-sysctl','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Apply Kernel Variables\nDocumentation=man:systemd-sysctl.service(8) man:sysctl.d(5)\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=systemd-modules-load.service\nBefore=sysinit.target shutdown.target\nConditionPathIsReadWrite=/proc/sys/net/\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-sysctl\nTimeoutSec=90s\nLoadCredential=sysctl.extra\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:05','2026-10-17 13:50:05'),(30,2039,1013,NULL,4630492758,129,'systemd-sysusers.service','systemd-sysusers','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create System Users\nDocumentation=man:sysusers.d(5) man:systemd-sysusers.service(8)\n\nDefaultDependencies=no\nAfter=systemd-remount-fs.service\nBefore=sysinit.target systemd-update-done.service\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\nConditionNeedsUpdate=|/etc\nConditionCredential=|sysusers.extra\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-sysusers\nTimeoutSec=90s\n\n# Optionally, pick up a root password and shell for the root user from a\n# credential passed to the service manager. This is useful for importing this\n# data from nspawn\'s --set-credential= switch.\nLoadCredential=passwd.hashed-password.root\nLoadCredential=passwd.plaintext-password.root\nLoadCredential=passwd.shell.root\n\n# Also, allow configuring extra sysusers lines via a credential\nLoadCredential=sysusers.extra\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:05','2026-10-17 13:50:05'),(31,2040,1013,NULL,4630492758,130,'systemd-timesyncd.service','systemd-timesyncd','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Network Time Synchronization\nDocumentation=man:systemd-timesyncd.service(8)\nConditionCapability=CAP_SYS_TIME\nConditionVirtualization=!container\nDefaultDependencies=no\nAfter=systemd-sysusers.service\nBefore=time-set.target sysinit.target shutdown.target\nConflicts=shutdown.target\nWants=time-set.target\n\n[Service]\nAmbientCapabilities=CAP_SYS_TIME\nBusName=org.freedesktop.timesync1\nCapabilityBoundingSet=CAP_SYS_TIME\n# Turn off DNSSEC validation for hostname look-ups, since those need the\n# correct time to work, but we likely won\'t acquire that without NTP. Let\'s\n# break this chicken-and-egg cycle here.\nEnvironment=SYSTEMD_NSS_RESOLVE_VALIDATE=0\nExecStart=!!/lib/systemd/systemd-timesyncd\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateDevices=yes\nPrivateTmp=yes\nProtectProc=invisible\nProtectControlGroups=yes\nProtectHome=yes\nProtectHostname=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectKernelTunables=yes\nProtectSystem=strict\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_INET AF_INET6\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/timesync\nStateDirectory=systemd/timesync\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service @clock\nType=notify\nUser=systemd-timesync\nWatchdogSec=3min\n\n[Install]\nWantedBy=sysinit.target\nAlias=dbus-org.freedesktop.timesync1.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:05','2026-10-17 13:50:05'),(32,2041,1013,NULL,4630492758,131,'systemd-tmpfiles-setup-dev.service','systemd-tmpfiles-setup-dev','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create Static Device Nodes in /dev\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nAfter=systemd-sysusers.service\nBefore=sysinit.target local-fs-pre.target systemd-udevd.service\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --prefix=/dev --create --boot\nSuccessExitStatus=DATAERR CANTCREAT\nLoadCredential=tmpfiles.extra\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:06','2026-10-17 13:50:06'),(33,2042,1013,NULL,4630492758,132,'systemd-tmpfiles-setup.service','systemd-tmpfiles-setup','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create System Files and Directories\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nAfter=local-fs.target systemd-sysusers.service systemd-journald.service\nBefore=sysinit.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\nRefuseManualStop=yes\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --create --remove --boot --exclude-prefix=/dev\nSuccessExitStatus=DATAERR CANTCREAT\nLoadCredential=tmpfiles.extra\nLoadCredential=login.motd\nLoadCredential=login.issue\nLoadCredential=network.hosts\nLoadCredential=ssh.authorized_keys.root\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:06','2026-10-17 13:50:06'),(34,2043,1013,NULL,4630492758,133,'systemd-udev-trigger.service','systemd-udev-trigger','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Coldplug All udev Devices\nDocumentation=man:udev(7) man:systemd-udevd.service(8)\nDefaultDependencies=no\nWants=systemd-udevd.service\nAfter=systemd-udevd-kernel.socket systemd-udevd-control.socket\nBefore=sysinit.target\nConditionPathIsReadWrite=/sys\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=-udevadm trigger --type=all --action=add --prioritized-subsystem=module,block,tpmrm,net,tty,input\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:06','2026-10-17 13:50:06'),(35,2044,1013,NULL,4630492758,134,'systemd-udevd.service','systemd-udevd','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Rule-based Manager for Device Events and Files\nDocumentation=man:systemd-udevd.service(8) man:udev(7)\nDefaultDependencies=no\nAfter=systemd-sysusers.service systemd-hwdb-update.service\nBefore=sysinit.target\nConditionPathIsReadWrite=/sys\n\n[Service]\nCapabilityBoundingSet=~CAP_SYS_TIME CAP_WAKE_ALARM\nDelegate=pids\nType=notify\n# Note that udev will reset the value internally for its workers\nOOMScoreAdjust=-1000\nSockets=systemd-udevd-control.socket systemd-udevd-kernel.socket\nRestart=always\nRestartSec=0\nExecStart=/lib/systemd/systemd-udevd\nExecReload=udevadm control --reload --timeout 0\nKillMode=mixed\nTasksMax=infinity\nPrivateMounts=yes\nProtectHostname=yes\nMemoryDenyWriteExecute=yes\nRestrictAddressFamilies=AF_UNIX AF_NETLINK AF_INET AF_INET6\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nSystemCallFilter=@system-service @module @raw-io bpf\nSystemCallFilter=~@clock\nSystemCallErrorNumber=EPERM\nLockPersonality=yes\nIPAddressDeny=any\nWatchdogSec=3min\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:07','2026-10-17 13:50:07'),(36,2045,1013,NULL,4630492758,135,'systemd-update-utmp.service','systemd-update-utmp','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Record System Boot/Shutdown in UTMP\nDocumentation=man:systemd-update-utmp.service(8) man:utmp(5)\nDefaultDependencies=no\nRequiresMountsFor=/var/log/wtmp\nConflicts=shutdown.target\nAfter=systemd-remount-fs.service systemd-tmpfiles-setup.service auditd.service\nBefore=sysinit.target shutdown.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-update-utmp reboot\nExecStop=/lib/systemd/systemd-update-utmp shutdown\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:07','2026-10-17 13:50:07'),(37,2046,1013,NULL,4630492758,136,'systemd-user-sessions.service','systemd-user-sessions','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Permit User Sessions\nDocumentation=man:systemd-user-sessions.service(8)\nAfter=remote-fs.target nss-user-lookup.target network.target home.mount\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/lib/systemd/systemd-user-sessions start\nExecStop=/lib/systemd/systemd-user-sessions stop\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:08','2026-10-17 13:50:08'),(38,2047,1013,NULL,4630492758,137,'tailscaled.service','tailscaled','[Unit]\nDescription=Tailscale node agent\nDocumentation=https://tailscale.com/docs/\nWants=network-pre.target\nAfter=network-pre.target NetworkManager.service systemd-resolved.service\n\n[Service]\nEnvironmentFile=/etc/default/tailscaled\nExecStart=/usr/sbin/tailscaled --state=/var/lib/tailscale/tailscaled.state --socket=/run/tailscale/tailscaled.sock --port=${PORT} $FLAGS\nExecStopPost=/usr/sbin/tailscaled --cleanup\n\nRestart=on-failure\n\nRuntimeDirectory=tailscale\nRuntimeDirectoryMode=0755\nStateDirectory=tailscale\nStateDirectoryMode=0700\nCacheDirectory=tailscale\nCacheDirectoryMode=0750\nType=notify\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:08','2026-10-17 13:50:08'),(39,2048,1013,NULL,4630492758,138,'triggerhappy.service','triggerhappy','[Unit]\nDescription=triggerhappy global hotkey daemon\nAfter=local-fs.target\n\n[Service]\nType=notify\nExecStart=/usr/sbin/thd --triggers /etc/triggerhappy/triggers.d/ --socket /run/thd.socket --user nobody --deviceglob /dev/input/event*\n\n[Install]\nWantedBy=multi-user.target\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:08','2026-10-17 13:50:08'),(40,2049,1013,NULL,4630492758,139,'user-runtime-dir@.service','user-runtime-dir@1000','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Runtime Directory /run/user/%i\nDocumentation=man:user@.service(5)\nAfter=dbus.service\nStopWhenUnneeded=yes\nIgnoreOnIsolate=yes\n\n[Service]\nExecStart=/lib/systemd/systemd-user-runtime-dir start %i\nExecStop=/lib/systemd/systemd-user-runtime-dir stop %i\nType=oneshot\nRemainAfterExit=yes\nSlice=user-%i.slice\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:09','2026-10-17 13:50:09'),(41,2050,1013,NULL,4630492758,140,'user@.service','user@1000','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Manager for UID %i\nDocumentation=man:user@.service(5)\nAfter=user-runtime-dir@%i.service dbus.service systemd-oomd.service\nRequires=user-runtime-dir@%i.service\nIgnoreOnIsolate=yes\n\n[Service]\nUser=%i\nPAMName=systemd-user\nType=notify\nExecStart=/lib/systemd/systemd --user\nSlice=user-%i.slice\nKillMode=mixed\nDelegate=pids memory cpu\nTasksMax=infinity\nTimeoutStopSec=120s\nKeyringMode=inherit\nOOMScoreAdjust=100\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:09','2026-10-17 13:50:09'),(42,2051,1013,NULL,4630492758,141,'wpa_supplicant.service','wpa_supplicant','[Unit]\nDescription=WPA supplicant\nBefore=network.target\nAfter=dbus.service\nWants=network.target\nIgnoreOnIsolate=true\n\n[Service]\nType=dbus\nBusName=fi.w1.wpa_supplicant1\nExecStart=/sbin/wpa_supplicant -u -s -O \"DIR=/run/wpa_supplicant GROUP=netdev\"\nExecReload=/bin/kill -HUP $MAINPID\nGroup=netdev\nRuntimeDirectory=wpa_supplicant\nRuntimeDirectoryMode=0750\n\n[Install]\nWantedBy=multi-user.target\nAlias=dbus-fi.w1.wpa_supplicant1.service\n','61cbaf46a0f1c5a5f80965e05ef9434b484592db4787f4f5b974ad903021b726','v1','active','2026-10-17 13:50:09','2026-10-17 13:50:09'),(43,2052,1013,NULL,582108557,142,'ModemManager.service','ModemManager','[Unit]\nDescription=Modem Manager\nAfter=polkit.service\nRequires=polkit.service\nConditionVirtualization=!container\n\n[Service]\nType=dbus\nBusName=org.freedesktop.ModemManager1\nExecStart=/usr/sbin/ModemManager\nStandardError=null\nRestart=on-abort\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN\nProtectSystem=true\nProtectHome=true\nPrivateTmp=true\nRestrictAddressFamilies=AF_NETLINK AF_UNIX AF_QIPCRTR\nNoNewPrivileges=true\nUser=root\n\n[Install]\nWantedBy=multi-user.target\nAlias=dbus-org.freedesktop.ModemManager1.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:16','2026-10-17 13:50:16'),(44,2053,1013,NULL,582108557,143,'NetworkManager-wait-online.service','NetworkManager-wait-online','[Unit]\nDescription=Network Manager Wait Online\nDocumentation=man:NetworkManager-wait-online.service(8)\nRequires=NetworkManager.service\nAfter=NetworkManager.service\nBefore=network-online.target\n\n[Service]\n# `nm-online -s` waits until the point when NetworkManager logs\n# \"startup complete\". That is when startup actions are settled and\n# devices and profiles reached a conclusive activated or deactivated\n# state. It depends on which profiles are configured to autoconnect and\n# also depends on profile settings like ipv4.may-fail/ipv6.may-fail,\n# which affect when a profile is considered fully activated.\n# Check NetworkManager logs to find out why wait-online takes a certain\n# time.\n\nType=oneshot\nExecStart=/usr/bin/nm-online -s -q\nRemainAfterExit=yes\n\n# Set $NM_ONLINE_TIMEOUT variable for timeout in seconds.\n# Edit with `systemctl edit NetworkManager-wait-online`.\n#\n# Note, this timeout should commonly not be reached. If your boot\n# gets delayed too long, then the solution is usually not to decrease\n# the timeout, but to fix your setup so that the connected state\n# gets reached earlier.\nEnvironment=NM_ONLINE_TIMEOUT=60\n\n[Install]\nWantedBy=network-online.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:17','2026-10-17 13:50:17'),(45,2054,1013,NULL,582108557,144,'NetworkManager.service','NetworkManager','[Unit]\nDescription=Network Manager\nDocumentation=man:NetworkManager(8)\nWants=network.target\nAfter=network-pre.target dbus.service\nBefore=network.target \nBindsTo=dbus.service\n\n[Service]\nType=dbus\nBusName=org.freedesktop.NetworkManager\nExecReload=/usr/bin/busctl call org.freedesktop.NetworkManager /org/freedesktop/NetworkManager org.freedesktop.NetworkManager Reload u 0\n#ExecReload=/bin/kill -HUP $MAINPID\nExecStart=/usr/sbin/NetworkManager --no-daemon\nRestart=on-failure\n# NM doesn\'t want systemd to kill its children for it\nKillMode=process\n\n# With a huge number of interfaces, starting can take a long time.\nTimeoutStartSec=600\n\nCapabilityBoundingSet=CAP_NET_ADMIN CAP_DAC_OVERRIDE CAP_NET_RAW CAP_NET_BIND_SERVICE CAP_SETGID CAP_SETUID CAP_SYS_MODULE CAP_AUDIT_WRITE CAP_KILL CAP_SYS_CHROOT\n\nProtectSystem=true\nProtectHome=read-only\nReadWritePaths=/usr/lib/netplan\n\n# We require file descriptors for DHCP etc. When activating many interfaces,\n# the default limit of 1024 is easily reached.\nLimitNOFILE=65536\n\n[Install]\nWantedBy=multi-user.target\nAlso=NetworkManager-dispatcher.service\n\n# We want to enable NetworkManager-wait-online.service whenever this service\n# is enabled. NetworkManager-wait-online.service has\n# WantedBy=network-online.target, so enabling it only has an effect if\n# network-online.target itself is enabled or pulled in by some other unit.\nAlso=NetworkManager-wait-online.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:17','2026-10-17 13:50:17'),(46,2055,1013,NULL,582108557,145,'alsa-restore.service','alsa-restore','#\n# Note that two different ALSA card state management schemes exist and they\n# can be switched using a file exist check - /etc/alsa/state-daemon.conf .\n#\n\n[Unit]\nDescription=Save/Restore Sound Card State\nDocumentation=man:alsactl(1)\nConditionPathExists=!/etc/alsa/state-daemon.conf\nConditionPathExistsGlob=/dev/snd/control*\nAfter=alsa-state.service\n\n[Service]\nType=oneshot\nRemainAfterExit=true\nExecStart=-/usr/sbin/alsactl -E HOME=/run/alsa -E XDG_RUNTIME_DIR=/run/alsa/runtime restore\nExecStop=-/usr/sbin/alsactl -E HOME=/run/alsa -E XDG_RUNTIME_DIR=/run/alsa/runtime store\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:18','2026-10-17 13:50:18'),(47,2056,1013,NULL,582108557,146,'avahi-daemon.service','avahi-daemon','# This file is part of avahi.\n#\n# avahi is free software; you can redistribute it and/or modify it\n# under the terms of the GNU Lesser General Public License as\n# published by the Free Software Foundation; either version 2 of the\n# License, or (at your option) any later version.\n#\n# avahi is distributed in the hope that it will be useful, but WITHOUT\n# ANY WARRANTY; without even the implied warranty of MERCHANTABILITY\n# or FITNESS FOR A PARTICULAR PURPOSE. See the GNU General Public\n# License for more details.\n#\n# You should have received a copy of the GNU Lesser General Public\n# License along with avahi; if not, write to the Free Software\n# Foundation, Inc., 59 Temple Place, Suite 330, Boston, MA 02111-1307\n# USA.\n\n[Unit]\nDescription=Avahi mDNS/DNS-SD Stack\nRequires=avahi-daemon.socket\n\n[Service]\nType=dbus\nBusName=org.freedesktop.Avahi\nExecStart=/usr/sbin/avahi-daemon -s\nExecReload=/usr/sbin/avahi-daemon -r\nNotifyAccess=main\n\n[Install]\nWantedBy=multi-user.target\nAlso=avahi-daemon.socket\nAlias=dbus-org.freedesktop.Avahi.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:18','2026-10-17 13:50:18'),(48,2057,1013,NULL,582108557,147,'bluetooth.service','bluetooth','[Unit]\nDescription=Bluetooth service\nDocumentation=man:bluetoothd(8)\nConditionPathIsDirectory=/sys/class/bluetooth\n\n[Service]\nType=dbus\nBusName=org.bluez\nExecStart=/usr/libexec/bluetooth/bluetoothd\nNotifyAccess=main\n#WatchdogSec=10\nRestart=on-failure\nCapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE\nLimitNPROC=1\n\n# Filesystem lockdown\nProtectHome=true\nProtectSystem=strict\nPrivateTmp=true\nProtectKernelTunables=true\nProtectControlGroups=true\nStateDirectory=bluetooth\nStateDirectoryMode=0700\nConfigurationDirectory=bluetooth\nConfigurationDirectoryMode=0555\n\n# Execute Mappings\nMemoryDenyWriteExecute=true\n\n# Privilege escalation\nNoNewPrivileges=true\n\n# Real-time\nRestrictRealtime=true\n\n[Install]\nWantedBy=bluetooth.target\nAlias=dbus-org.bluez.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:18','2026-10-17 13:50:18'),(49,2058,1013,NULL,582108557,148,'cloud-config.service','cloud-config','[Unit]\n# https://docs.cloud-init.io/en/latest/explanation/boot.html\nDescription=Cloud-init: Config Stage\nAfter=network-online.target cloud-config.target\nWants=network-online.target cloud-config.target\nConditionPathExists=!/etc/cloud/cloud-init.disabled\nConditionKernelCommandLine=!cloud-init=disabled\nConditionEnvironment=!KERNEL_CMDLINE=cloud-init=disabled\n\n[Service]\nType=oneshot\n# This service is a shim which preserves systemd ordering while allowing a\n# single Python process to run cloud-init\'s logic. This works by communicating\n# with the cloud-init process over a unix socket to tell the process that this\n# stage can start, and then wait on a return socket until the cloud-init\n# process has completed this stage. The output from the return socket is piped\n# into a shell so that the process can send a completion message (defaults to\n# \"done\", otherwise includes an error message) and an exit code to systemd.\nExecStart=sh -c \'echo \"start\" | nc -Uu -W1 /run/cloud-init/share/config.sock -s /run/cloud-init/share/config-return.sock | sh\'\nRemainAfterExit=yes\nTimeoutSec=0\n\n# Output needs to appear in instance console output\nStandardOutput=journal+console\n\n[Install]\nWantedBy=cloud-init.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:19','2026-10-17 13:50:19'),(50,2059,1013,NULL,582108557,149,'cloud-final.service','cloud-final','[Unit]\n# https://docs.cloud-init.io/en/latest/explanation/boot.html\nDescription=Cloud-init: Final Stage\nAfter=network-online.target time-sync.target cloud-config.service rc-local.service\nAfter=multi-user.target\nBefore=apt-daily.service\nWants=network-online.target cloud-config.service\nConditionPathExists=!/etc/cloud/cloud-init.disabled\nConditionKernelCommandLine=!cloud-init=disabled\nConditionEnvironment=!KERNEL_CMDLINE=cloud-init=disabled\n\n\n[Service]\nType=oneshot\n# This service is a shim which preserves systemd ordering while allowing a\n# single Python process to run cloud-init\'s logic. This works by communicating\n# with the cloud-init process over a unix socket to tell the process that this\n# stage can start, and then wait on a return socket until the cloud-init\n# process has completed this stage. The output from the return socket is piped\n# into a shell so that the process can send a completion message (defaults to\n# \"done\", otherwise includes an error message) and an exit code to systemd.\nExecStart=sh -c \'echo \"start\" | nc -Uu -W1 /run/cloud-init/share/final.sock -s /run/cloud-init/share/final-return.sock | sh\'\nRemainAfterExit=yes\nTimeoutSec=0\nTasksMax=infinity\n\n# Output needs to appear in instance console output\nStandardOutput=journal+console\n\n[Install]\nWantedBy=cloud-init.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:19','2026-10-17 13:50:19'),(51,2060,1013,NULL,582108557,150,'cloud-init-local.service','cloud-init-local','[Unit]\n# https://docs.cloud-init.io/en/latest/explanation/boot.html\nDescription=Cloud-init: Local Stage (pre-network)\nDefaultDependencies=no\nWants=network-pre.target\nAfter=hv_kvp_daemon.service\nBefore=auditd.service\nBefore=network-pre.target\nBefore=shutdown.target\nBefore=sysinit.target\nConflicts=shutdown.target\nConditionPathExists=!/etc/cloud/cloud-init.disabled\nConditionKernelCommandLine=!cloud-init=disabled\nConditionEnvironment=!KERNEL_CMDLINE=cloud-init=disabled\n\n[Service]\nType=oneshot\n# This service is a shim which preserves systemd ordering while allowing a\n# single Python process to run cloud-init\'s logic. This works by communicating\n# with the cloud-init process over a unix socket to tell the process that this\n# stage can start, and then wait on a return socket until the cloud-init\n# process has completed this stage. The output from the return socket is piped\n# into a shell so that the process can send a completion message (defaults to\n# \"done\", otherwise includes an error message) and an exit code to systemd.\nExecStart=sh -c \'echo \"start\" | nc -Uu -W1 /run/cloud-init/share/local.sock -s /run/cloud-init/share/local-return.sock | sh\'\nRemainAfterExit=yes\nTimeoutSec=0\n\n# Output needs to appear in instance console output\nStandardOutput=journal+console\n\n[Install]\nWantedBy=cloud-init.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:20','2026-10-17 13:50:20'),(52,2061,1013,NULL,582108557,151,'cloud-init-network.service','cloud-init-network','[Unit]\n# https://docs.cloud-init.io/en/latest/explanation/boot.html\nDescription=Cloud-init: Network Stage\nDefaultDependencies=no\nWants=cloud-init-local.service\nWants=sshd-keygen.service\nWants=sshd.service\nAfter=cloud-init-local.service\nAfter=networking.service\nBefore=network-online.target\nBefore=chronyd.service\nBefore=sshd-keygen.service\nBefore=sshd.service\nBefore=systemd-user-sessions.service\nBefore=sysinit.target\nBefore=shutdown.target\nConflicts=shutdown.target\nConditionPathExists=!/etc/cloud/cloud-init.disabled\nConditionKernelCommandLine=!cloud-init=disabled\nConditionEnvironment=!KERNEL_CMDLINE=cloud-init=disabled\n\n[Service]\nType=oneshot\n# This service is a shim which preserves systemd ordering while allowing a\n# single Python process to run cloud-init\'s logic. This works by communicating\n# with the cloud-init process over a unix socket to tell the process that this\n# stage can start, and then wait on a return socket until the cloud-init\n# process has completed this stage. The output from the return socket is piped\n# into a shell so that the process can send a completion message (defaults to\n# \"done\", otherwise includes an error message) and an exit code to systemd.\nExecStart=sh -c \'echo \"start\" | nc -Uu -W1 /run/cloud-init/share/network.sock -s /run/cloud-init/share/network-return.sock | sh\'\nRemainAfterExit=yes\nTimeoutSec=0\n\n# Output needs to appear in instance console output\nStandardOutput=journal+console\n\n[Install]\nWantedBy=cloud-init.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:20','2026-10-17 13:50:20'),(53,2062,1013,NULL,582108557,152,'console-setup.service','console-setup','[Unit]\nDescription=Set console font and keymap\nDefaultDependencies=no\nAfter=console-screen.service kbd.service local-fs.target\nBefore=display-manager.service\nRequiresMountsFor=/usr\nConditionPathExists=/bin/setupcon\n\n[Service]\nType=oneshot\nExecStart=/lib/console-setup/console-setup.sh\nRemainAfterExit=yes\n\n[Install]\nWantedBy=multi-user.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:20','2026-10-17 13:50:20'),(54,2063,1013,NULL,582108557,153,'containerd.service','containerd','# Copyright The containerd Authors.\n#\n# Licensed under the Apache License, Version 2.0 (the \"License\");\n# you may not use this file except in compliance with the License.\n# You may obtain a copy of the License at\n#\n#     http://www.apache.org/licenses/LICENSE-2.0\n#\n# Unless required by applicable law or agreed to in writing, software\n# distributed under the License is distributed on an \"AS IS\" BASIS,\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n# See the License for the specific language governing permissions and\n# limitations under the License.\n\n[Unit]\nDescription=containerd container runtime\nDocumentation=https://containerd.io\nAfter=network.target local-fs.target dbus.service\n\n[Service]\n#uncomment to enable the experimental sbservice (sandboxed) version of containerd/cri integration\n#Environment=\"ENABLE_CRI_SANDBOXES=sandboxed\"\nExecStartPre=-/sbin/modprobe overlay\nExecStart=/usr/bin/containerd\n\nType=notify\nDelegate=yes\nKillMode=process\nRestart=always\nRestartSec=5\n# Having non-zero Limit*s causes performance problems due to accounting overhead\n# in the kernel. We recommend using cgroups to do container-local accounting.\nLimitNPROC=infinity\nLimitCORE=infinity\nLimitNOFILE=infinity\n# Comment TasksMax if your systemd version does not supports it.\n# Only systemd 226 and above support this version.\nTasksMax=infinity\nOOMScoreAdjust=-999\n\n[Install]\nWantedBy=multi-user.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:21','2026-10-17 13:50:21'),(55,2064,1013,NULL,582108557,154,'cron.service','cron','[Unit]\nDescription=Regular background program processing daemon\nDocumentation=man:cron(8)\nAfter=remote-fs.target nss-user-lookup.target\n\n[Service]\nEnvironmentFile=-/etc/default/cron\nExecStart=/usr/sbin/cron -f $EXTRA_OPTS\nIgnoreSIGPIPE=false\nKillMode=process\nRestart=on-failure\nSyslogFacility=cron\n\n[Install]\nWantedBy=multi-user.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:21','2026-10-17 13:50:21'),(56,2065,1013,NULL,582108557,155,'dbus.service','dbus','[Unit]\nDescription=D-Bus System Message Bus\nDocumentation=man:dbus-daemon(1)\nRequires=dbus.socket\n\n[Service]\nType=notify\nNotifyAccess=main\nExecStart=/usr/bin/dbus-daemon --system --address=systemd: --nofork --nopidfile --systemd-activation --syslog-only\nExecReload=/usr/bin/dbus-send --print-reply --system --type=method_call --dest=org.freedesktop.DBus / org.freedesktop.DBus.ReloadConfig\nOOMScoreAdjust=-900\nUser=messagebus\nGroup=messagebus\nAmbientCapabilities=CAP_AUDIT_WRITE\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:21','2026-10-17 13:50:21'),(57,2066,1013,NULL,582108557,156,'docker.service','docker','[Unit]\nDescription=Docker Application Container Engine\nDocumentation=https://docs.docker.com\nAfter=network-online.target docker.socket firewalld.service containerd.service time-set.target\nWants=network-online.target containerd.service\nRequires=docker.socket\n\n[Service]\nType=notify\n# the default is not to use systemd for cgroups because the delegate issues still\n# exists and systemd currently does not support the cgroup feature set required\n# for containers run by docker\nEnvironmentFile=-/etc/default/docker\nExecStart=/usr/sbin/dockerd -H fd:// --containerd=/run/containerd/containerd.sock $DOCKER_OPTS\nExecReload=/bin/kill -s HUP $MAINPID\nTimeoutStartSec=0\nRestartSec=2\nRestart=always\n\n# Note that StartLimit* options were moved from \"Service\" to \"Unit\" in systemd 229.\n# Both the old, and new location are accepted by systemd 229 and up, so using the old location\n# to make them work for either version of systemd.\nStartLimitBurst=3\n\n# Note that StartLimitInterval was renamed to StartLimitIntervalSec in systemd 230.\n# Both the old, and new name are accepted by systemd 230 and up, so using the old name to make\n# this option work for either version of systemd.\nStartLimitInterval=60s\n\n# Having non-zero Limit*s causes performance problems due to accounting overhead\n# in the kernel. We recommend using cgroups to do container-local accounting.\nLimitNPROC=infinity\nLimitCORE=infinity\n\n# Comment TasksMax if your systemd version does not support it.\n# Only systemd 226 and above support this option.\nTasksMax=infinity\n\n# set delegate yes so that systemd does not reset the cgroups of docker containers\nDelegate=yes\n\n# kill only the docker process, not all processes in the cgroup\nKillMode=process\nOOMScoreAdjust=-500\n\n[Install]\nWantedBy=multi-user.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:22','2026-10-17 13:50:22'),(58,2067,1013,NULL,582108557,157,'getty@.service','getty@tty1','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Getty on %I\nDocumentation=man:agetty(8) man:systemd-getty-generator(8)\nDocumentation=https://0pointer.de/blog/projects/serial-console.html\nAfter=systemd-user-sessions.service plymouth-quit-wait.service getty-pre.target\nAfter=rc-local.service\n\n# If additional gettys are spawned during boot then we should make\n# sure that this is synchronized before getty.target, even though\n# getty.target didn\'t actually pull it in.\nBefore=getty.target\nIgnoreOnIsolate=yes\n\n# IgnoreOnIsolate causes issues with sulogin, if someone isolates\n# rescue.target or starts rescue.service from multi-user.target or\n# graphical.target.\nConflicts=rescue.service\nBefore=rescue.service\n\n# On systems without virtual consoles, don\'t start any getty. Note\n# that serial gettys are covered by serial-getty@.service, not this\n# unit.\nConditionPathExists=/dev/tty0\n\n[Service]\n# The \'-o\' option value tells agetty to replace \'login\' arguments with \'--\' for\n# safety, and then the entered username.\nExecStart=-/sbin/agetty -o \'-- \\\\u\' --noreset --noclear - ${TERM}\nType=idle\nRestart=always\nRestartSec=0\nUtmpIdentifier=%I\nStandardInput=tty\nStandardOutput=tty\nTTYPath=/dev/%I\nTTYReset=yes\nTTYVHangup=yes\nTTYVTDisallocate=yes\nIgnoreSIGPIPE=no\nSendSIGHUP=yes\nImportCredential=tty.virtual.%I.agetty.*:agetty.\nImportCredential=tty.virtual.%I.login.*:login.\nImportCredential=agetty.*\nImportCredential=login.*\nImportCredential=shell.*\n\n# Unset locale for the console getty since the console has problems\n# displaying some internationalized messages.\nUnsetEnvironment=LANG LANGUAGE LC_CTYPE LC_NUMERIC LC_TIME LC_COLLATE LC_MONETARY LC_MESSAGES LC_PAPER LC_NAME LC_ADDRESS LC_TELEPHONE LC_MEASUREMENT LC_IDENTIFICATION\n\n[Install]\nWantedBy=getty.target\nDefaultInstance=tty1\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:22','2026-10-17 13:50:22'),(59,2068,1013,NULL,582108557,158,'keyboard-setup.service','keyboard-setup','[Unit]\nDescription=Set the console keyboard layout\nDefaultDependencies=no\nBefore=local-fs-pre.target\nWants=local-fs-pre.target\nConditionPathExists=/bin/setupcon\n\n[Service]\nType=oneshot\nExecStart=/lib/console-setup/keyboard-setup.sh\nRemainAfterExit=yes\n\n[Install]\nWantedBy=sysinit.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:22','2026-10-17 13:50:22'),(60,2069,1013,NULL,582108557,159,'kmod-static-nodes.service','kmod-static-nodes','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create List of Static Device Nodes\nDefaultDependencies=no\nBefore=sysinit.target systemd-tmpfiles-setup-dev-early.service\nConditionCapability=CAP_SYS_MODULE\nConditionFileNotEmpty=/lib/modules/%v/modules.devname\nConditionPathExists=/usr/bin/kmod\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/bin/kmod static-nodes --format=tmpfiles --output=/run/tmpfiles.d/static-nodes.conf\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:23','2026-10-17 13:50:23'),(61,2070,1013,NULL,582108557,160,'polkit.service','polkit','[Unit]\nDescription=Authorization Manager\nDocumentation=man:polkit(8)\n\n[Service]\nType=notify-reload\nBusName=org.freedesktop.PolicyKit1\nCapabilityBoundingSet=CAP_SETUID CAP_SETGID\nDeviceAllow=/dev/null rw\nDevicePolicy=strict\nExecStart=/usr/lib/polkit-1/polkitd --no-debug --log-level=notice\nUser=polkitd\nLimitMEMLOCK=0\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateDevices=yes\nPrivateNetwork=yes\nPrivateTmp=yes\nProtectControlGroups=yes\nProtectHome=yes\nProtectKernelModules=yes\nProtectKernelLogs=yes\nProtectKernelTunables=yes\nProtectSystem=strict\nProtectClock=yes\nProtectHostname=yes\nRemoveIPC=yes\nRestrictAddressFamilies=AF_UNIX\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nSystemCallArchitectures=native\nSystemCallFilter=@system-service\nUMask=0077\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:23','2026-10-17 13:50:23'),(62,2071,1013,NULL,582108557,161,'rpi-eeprom-update.service','rpi-eeprom-update','[Unit]\nDescription=Check for Raspberry Pi EEPROM updates\nAfter=boot-firmware.mount\n\n[Service]\nType=oneshot\nRemainAfterExit=true\nExecStart=/usr/bin/rpi-eeprom-update -s -a\n\n[Install]\nWantedBy=multi-user.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:24','2026-10-17 13:50:24'),(63,2072,1013,NULL,582108557,162,'rpi-setup-loop@.service','rpi-setup-loop@var-swap','[Unit]\nDescription=rpi-setup-loop - set up file on loop device\n\n[Service]\nType=oneshot\nExecStart=/sbin/losetup --nooverlap --find /%I\nExecStartPost=/usr/lib/rpi-loop-utils/bin/rpi-wait-backingfile-symlink %i\nExecStop=/sbin/losetup -d /dev/disk/by-backingfile/%i\nRemainAfterExit=yes\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:24','2026-10-17 13:50:24'),(64,2073,1013,NULL,582108557,163,'ssh.service','ssh','[Unit]\nDescription=OpenBSD Secure Shell server\nDocumentation=man:sshd(8) man:sshd_config(5)\nAfter=network.target nss-user-lookup.target auditd.service\nConditionPathExists=!/etc/ssh/sshd_not_to_be_run\n\n[Service]\nEnvironmentFile=-/etc/default/ssh\nExecStartPre=/usr/sbin/sshd -t\nExecStart=/usr/sbin/sshd -D $SSHD_OPTS\nExecReload=/usr/sbin/sshd -t\nExecReload=/bin/kill -HUP $MAINPID\nKillMode=process\nRestart=on-failure\nRestartPreventExitStatus=255\nType=notify\nRuntimeDirectory=sshd\nRuntimeDirectoryMode=0755\n\n[Install]\nWantedBy=multi-user.target\nAlias=sshd.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:24','2026-10-17 13:50:24'),(65,2074,1013,NULL,582108557,164,'systemd-binfmt.service','systemd-binfmt','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Set Up Additional Binary Formats\nDocumentation=man:systemd-binfmt.service(8) man:binfmt.d(5)\nDocumentation=https://docs.kernel.org/admin-guide/binfmt-misc.html\nDocumentation=https://systemd.io/API_FILE_SYSTEMS\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=proc-sys-fs-binfmt_misc.automount\nAfter=proc-sys-fs-binfmt_misc.mount\nAfter=local-fs.target\nBefore=sysinit.target shutdown.target\nConditionPathIsMountPoint=/proc/sys/fs/binfmt_misc\nConditionDirectoryNotEmpty=|/lib/binfmt.d\nConditionDirectoryNotEmpty=|/usr/lib/binfmt.d\nConditionDirectoryNotEmpty=|/usr/local/lib/binfmt.d\nConditionDirectoryNotEmpty=|/etc/binfmt.d\nConditionDirectoryNotEmpty=|/run/binfmt.d\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-binfmt\nExecStop=/usr/lib/systemd/systemd-binfmt --unregister\nTimeoutSec=90s\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:25','2026-10-17 13:50:25'),(66,2075,1013,NULL,582108557,165,'systemd-fsck@.service','systemd-fsck@dev-disk-by\\x2dpartuuid-c3ebceb5\\x2d01','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=File System Check on %f\nDocumentation=man:systemd-fsck@.service(8)\nDefaultDependencies=no\nBindsTo=%i.device\nIgnoreOnIsolate=yes\nConflicts=reboot.target kexec.target poweroff.target halt.target\nAfter=%i.device systemd-fsck-root.service local-fs-pre.target\nBefore=systemd-quotacheck.service shutdown.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-fsck %f\nTimeoutSec=infinity\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:25','2026-10-17 13:50:25'),(67,2076,1013,NULL,582108557,166,'systemd-journal-flush.service','systemd-journal-flush','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Flush Journal to Persistent Storage\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\n\nConditionPathExists=!/etc/initrd-release\n\nDefaultDependencies=no\nAfter=systemd-remount-fs.service systemd-quotacheck-root.service\nBefore=systemd-tmpfiles-setup.service\nWants=systemd-journald.service\nAfter=systemd-journald.service\nRequiresMountsFor=/var/log/journal\n\nBefore=soft-reboot.target systemd-soft-reboot.service\nConflicts=soft-reboot.target\n\n[Service]\nExecStart=journalctl --flush\nExecStop=journalctl --smart-relinquish-var\nType=oneshot\nRemainAfterExit=yes\nTimeoutSec=90s\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:26','2026-10-17 13:50:26'),(68,2077,1013,NULL,582108557,167,'systemd-journald.service','systemd-journald','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Journal Service\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\nDefaultDependencies=no\nRequires=systemd-journald.socket\nAfter=systemd-journald.socket systemd-journald-dev-log.socket systemd-journald-audit.socket syslog.socket\nBefore=sysinit.target\n\n# To avoid journald SIGKILLed during soft-reboot and corrupting journals.\n# See https://github.com/systemd/systemd/issues/30195\n# Note, typically soft-reboot.target will be never reached,\n# and systemd-soft-reboot.service will trigger soft-reboot.\n# Hence, this must be stopped before systemd-soft-reboot.service.\nBefore=soft-reboot.target systemd-soft-reboot.service\nConflicts=soft-reboot.target\n\n# Mount and swap units need the journal socket units. If they were removed by\n# an isolate request the mount and swap units would be removed too, hence let\'s\n# exclude systemd-journald and its sockets from isolate requests.\nIgnoreOnIsolate=yes\n\n[Service]\nDeviceAllow=char-* rw\nExecStart=/usr/lib/systemd/systemd-journald\nFileDescriptorStoreMax=4224\n# Ensure services using StandardOutput=journal do not break when journald is stopped\nFileDescriptorStorePreserve=yes\nImportCredential=journal.*\nIPAddressDeny=any\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nOOMScoreAdjust=-250\nProtectClock=yes\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK AF_VSOCK AF_INET AF_INET6\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/journal\nRuntimeDirectoryPreserve=yes\n# Audit socket is not listed here because this unit can be turned off. However\n# the link between the socket and the service units is still created thanks to\n# the \'Service=\' setting specified in the socket unit.\nSockets=systemd-journald.socket systemd-journald-dev-log.socket\nStandardOutput=null\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nType=notify\nPassEnvironment=TERM\nWatchdogSec=3min\n\n# In case you\'re wondering why CAP_SYS_PTRACE is needed, access to\n# /proc/<pid>/exe requires this capability. Thus if this capability is missing\n# the _EXE=/OBJECT_EXE= fields will be missing from the journal entries.\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_DAC_OVERRIDE CAP_SYS_PTRACE CAP_SYSLOG CAP_AUDIT_CONTROL CAP_AUDIT_READ CAP_CHOWN CAP_DAC_READ_SEARCH CAP_FOWNER CAP_SETUID CAP_SETGID CAP_MAC_OVERRIDE\n\n# If there are many split up journal files we need a lot of fds to access them\n# all in parallel.\nLimitNOFILE=524288\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:26','2026-10-17 13:50:26'),(69,2078,1013,NULL,582108557,168,'systemd-logind.service','systemd-logind','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Login Management\nDocumentation=man:sd-login(3)\nDocumentation=man:systemd-logind.service(8)\nDocumentation=man:logind.conf(5)\nDocumentation=man:org.freedesktop.login1(5)\n\nWants=user.slice modprobe@drm.service\nAfter=nss-user-lookup.target user.slice modprobe@drm.service\n\n# Ask for the dbus socket.\nWants=dbus.socket\nAfter=dbus.socket\n\n[Service]\nBusName=org.freedesktop.login1\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_MAC_ADMIN CAP_AUDIT_CONTROL CAP_CHOWN CAP_DAC_READ_SEARCH CAP_DAC_OVERRIDE CAP_FOWNER CAP_SYS_TTY_CONFIG CAP_LINUX_IMMUTABLE\nDeviceAllow=block-* r\nDeviceAllow=char-/dev/console rw\nDeviceAllow=char-drm rw\nDeviceAllow=char-hidraw rw\nDeviceAllow=char-hvc rw\nDeviceAllow=char-input rw\nDeviceAllow=char-tty rw\nDeviceAllow=char-vcs rw\nExecStart=/usr/lib/systemd/systemd-logind\nFileDescriptorStoreMax=768\nIPAddressDeny=any\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateTmp=yes\n# We don\'t use ProtectProc= since we need to look for usernames and tty for wall messages\nProtectClock=yes\nProtectControlGroups=yes\nProtectHome=yes\nProtectHostname=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectSystem=strict\nReadWritePaths=/etc /run\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/sessions systemd/seats systemd/users systemd/inhibit systemd/shutdown\nRuntimeDirectoryPreserve=yes\nStateDirectory=systemd/linger\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nType=notify-reload\nWatchdogSec=3min\n\n# Increase the default a bit in order to allow many simultaneous logins since\n# we keep one fd open per session.\nLimitNOFILE=524288\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:26','2026-10-17 13:50:26'),(70,2079,1013,NULL,582108557,169,'systemd-modules-load.service','systemd-modules-load','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Load Kernel Modules\nDocumentation=man:systemd-modules-load.service(8) man:modules-load.d(5)\nDefaultDependencies=no\nConflicts=shutdown.target\nBefore=sysinit.target shutdown.target\nConditionCapability=CAP_SYS_MODULE\nConditionDirectoryNotEmpty=|/lib/modules-load.d\nConditionDirectoryNotEmpty=|/usr/lib/modules-load.d\nConditionDirectoryNotEmpty=|/usr/local/lib/modules-load.d\nConditionDirectoryNotEmpty=|/etc/modules-load.d\nConditionDirectoryNotEmpty=|/run/modules-load.d\nConditionKernelCommandLine=|modules-load\nConditionKernelCommandLine=|modules_load\nConditionKernelCommandLine=|rd.modules-load\nConditionKernelCommandLine=|rd.modules_load\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-modules-load\nTimeoutSec=90s\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:27','2026-10-17 13:50:27'),(71,2080,1013,NULL,582108557,170,'systemd-random-seed.service','systemd-random-seed','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Load/Save OS Random Seed\nDocumentation=man:systemd-random-seed.service(8) man:random(4)\n\nConditionVirtualization=!container\nConditionPathExists=!/etc/initrd-release\n\nDefaultDependencies=no\nAfter=systemd-remount-fs.service\nBefore=first-boot-complete.target\nRequiresMountsFor=/var/lib/systemd/random-seed\nWants=first-boot-complete.target\nConflicts=shutdown.target\nBefore=shutdown.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-random-seed load\nExecStop=/usr/lib/systemd/systemd-random-seed save\n\n# This service waits until the kernel\'s entropy pool is initialized, and may be\n# used as ordering barrier for service that require an initialized entropy\n# pool. Since initialization can take a while on entropy-starved systems, let\'s\n# increase the timeout substantially here.\nTimeoutSec=10min\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:27','2026-10-17 13:50:27'),(72,2081,1013,NULL,582108557,171,'systemd-remount-fs.service','systemd-remount-fs','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Remount Root and Kernel File Systems\nDocumentation=man:systemd-remount-fs.service(8)\nDocumentation=https://systemd.io/API_FILE_SYSTEMS\n\nDefaultDependencies=no\nAfter=systemd-fsck-root.service\nBefore=local-fs-pre.target local-fs.target\nWants=local-fs-pre.target\nConflicts=shutdown.target\nBefore=shutdown.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-remount-fs\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:28','2026-10-17 13:50:28'),(73,2082,1013,NULL,582108557,172,'systemd-sysctl.service','systemd-sysctl','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Apply Kernel Variables\nDocumentation=man:systemd-sysctl.service(8) man:sysctl.d(5)\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=systemd-modules-load.service\nBefore=sysinit.target shutdown.target\nConditionPathIsReadWrite=/proc/sys/net/\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-sysctl\nTimeoutSec=90s\nImportCredential=sysctl.*\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:28','2026-10-17 13:50:28'),(74,2083,1013,NULL,582108557,173,'systemd-timesyncd.service','systemd-timesyncd','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Network Time Synchronization\nDocumentation=man:systemd-timesyncd.service(8)\nConditionCapability=CAP_SYS_TIME\nConditionVirtualization=!container\nDefaultDependencies=no\nAfter=systemd-sysusers.service\nBefore=time-set.target sysinit.target shutdown.target\nConflicts=shutdown.target\nWants=time-set.target\n\n[Service]\nAmbientCapabilities=CAP_SYS_TIME\nBusName=org.freedesktop.timesync1\nCapabilityBoundingSet=CAP_SYS_TIME\n# Turn off DNSSEC validation for hostname look-ups, since those need the\n# correct time to work, but we likely won\'t acquire that without NTP. Let\'s\n# break this chicken-and-egg cycle here.\nEnvironment=SYSTEMD_NSS_RESOLVE_VALIDATE=0\nExecStart=!!/usr/lib/systemd/systemd-timesyncd\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateDevices=yes\nPrivateTmp=disconnected\nProtectProc=invisible\nProtectControlGroups=yes\nProtectHome=yes\nProtectHostname=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectKernelTunables=yes\nProtectSystem=strict\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_INET AF_INET6\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/timesync\nStateDirectory=systemd/timesync\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service @clock\nType=notify\nUser=systemd-timesync\nWatchdogSec=3min\n\n[Install]\nWantedBy=sysinit.target\nAlias=dbus-org.freedesktop.timesync1.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:28','2026-10-17 13:50:28'),(75,2084,1013,NULL,582108557,174,'systemd-tmpfiles-setup-dev-early.service','systemd-tmpfiles-setup-dev-early','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create Static Device Nodes in /dev gracefully\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nBefore=sysinit.target local-fs-pre.target systemd-udevd.service\nWants=local-fs-pre.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --prefix=/dev --create --boot --graceful\nSuccessExitStatus=DATAERR CANTCREAT\nImportCredential=tmpfiles.*\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:29','2026-10-17 13:50:29'),(76,2085,1013,NULL,582108557,175,'systemd-tmpfiles-setup-dev.service','systemd-tmpfiles-setup-dev','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create Static Device Nodes in /dev\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nAfter=systemd-tmpfiles-setup-dev-early.service\nBefore=sysinit.target local-fs-pre.target systemd-udevd.service\nWants=local-fs-pre.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --prefix=/dev --create --boot\nSuccessExitStatus=DATAERR CANTCREAT\nImportCredential=tmpfiles.*\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:29','2026-10-17 13:50:29'),(77,2086,1013,NULL,582108557,176,'systemd-tmpfiles-setup.service','systemd-tmpfiles-setup','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create System Files and Directories\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nAfter=local-fs.target systemd-sysusers.service systemd-journald.service\nBefore=sysinit.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\nRefuseManualStop=yes\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --create --remove --boot --exclude-prefix=/dev\nSuccessExitStatus=DATAERR CANTCREAT\nImportCredential=tmpfiles.*\nImportCredential=login.motd\nImportCredential=login.issue\nImportCredential=network.hosts\nImportCredential=ssh.authorized_keys.root\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:30','2026-10-17 13:50:30'),(78,2087,1013,NULL,582108557,177,'systemd-udev-load-credentials.service','systemd-udev-load-credentials','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Load udev Rules from Credentials\nDocumentation=man:udevadm(8)\nDocumentation=man:udev(7)\nDocumentation=man:systemd.system-credentials(7)\n\nDefaultDependencies=no\nBefore=systemd-udevd.service\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=udevadm control --load-credentials\nImportCredential=udev.conf.*\nImportCredential=udev.rules.*\n\n[Install]\nWantedBy=sysinit.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:30','2026-10-17 13:50:30'),(79,2088,1013,NULL,582108557,178,'systemd-udev-trigger.service','systemd-udev-trigger','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Coldplug All udev Devices\nDocumentation=man:udev(7) man:systemd-udevd.service(8)\nDefaultDependencies=no\nWants=systemd-udevd.service\nAfter=systemd-udevd-kernel.socket systemd-udevd-control.socket\nBefore=sysinit.target\nConditionPathIsReadWrite=/sys\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=-udevadm trigger --type=all --action=add --prioritized-subsystem=module,block,tpmrm,net,tty,input\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:30','2026-10-17 13:50:30'),(80,2089,1013,NULL,582108557,179,'systemd-udevd.service','systemd-udevd','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Rule-based Manager for Device Events and Files\nDocumentation=man:systemd-udevd.service(8) man:udev(7)\nDefaultDependencies=no\nAfter=systemd-sysusers.service systemd-hwdb-update.service\nBefore=sysinit.target\nWants=systemd-udev-load-credentials.service\nConditionPathIsReadWrite=/sys\n\n[Service]\nCapabilityBoundingSet=~CAP_SYS_TIME CAP_WAKE_ALARM\nDelegate=pids\nDelegateSubgroup=udev\nType=notify-reload\n# Note that udev will reset the value internally for its workers\nOOMScoreAdjust=-1000\nSockets=systemd-udevd-control.socket systemd-udevd-kernel.socket\nRestart=always\nRestartSec=0\nExecStart=/usr/lib/systemd/systemd-udevd\nKillMode=mixed\nTasksMax=infinity\nPrivateMounts=yes\nProtectHostname=yes\nMemoryDenyWriteExecute=yes\nRestrictAddressFamilies=AF_UNIX AF_NETLINK AF_INET AF_INET6\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nSystemCallFilter=@system-service @module @raw-io bpf\nSystemCallFilter=~@clock\nSystemCallErrorNumber=EPERM\nSystemCallArchitectures=native\nLockPersonality=yes\nIPAddressDeny=any\nWatchdogSec=3min\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:31','2026-10-17 13:50:31'),(81,2090,1013,NULL,582108557,180,'systemd-user-sessions.service','systemd-user-sessions','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Permit User Sessions\nDocumentation=man:systemd-user-sessions.service(8)\nAfter=remote-fs.target nss-user-lookup.target network.target home.mount\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-user-sessions start\nExecStop=/usr/lib/systemd/systemd-user-sessions stop\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:31','2026-10-17 13:50:31'),(82,2091,1013,NULL,582108557,181,'systemd-zram-setup@.service','systemd-zram-setup@zram0','# SPDX-License-Identifier: MIT\n# This file is part of the zram-generator project\n# https://github.com/systemd/zram-generator\n\n[Unit]\nDescription=Create swap on /dev/%i\nDocumentation=man:zram-generator(8) man:zram-generator.conf(5)\nAfter=dev-%i.device\nDefaultDependencies=false\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/system-generators/zram-generator --setup-device \'%i\'\nExecStop=/usr/lib/systemd/system-generators/zram-generator --reset-device \'%i\'\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:31','2026-10-17 13:50:31'),(83,2092,1013,NULL,582108557,182,'tailscaled.service','tailscaled','[Unit]\nDescription=Tailscale node agent\nDocumentation=https://tailscale.com/docs/\nWants=network-pre.target\nAfter=network-pre.target NetworkManager.service systemd-resolved.service\n\n[Service]\nEnvironmentFile=/etc/default/tailscaled\nExecStart=/usr/sbin/tailscaled --state=/var/lib/tailscale/tailscaled.state --socket=/run/tailscale/tailscaled.sock --port=${PORT} $FLAGS\nExecStopPost=/usr/sbin/tailscaled --cleanup\n\nRestart=on-failure\n\nRuntimeDirectory=tailscale\nRuntimeDirectoryMode=0755\nStateDirectory=tailscale\nStateDirectoryMode=0700\nCacheDirectory=tailscale\nCacheDirectoryMode=0750\nType=notify\n\n[Install]\nWantedBy=multi-user.target\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:32','2026-10-17 13:50:32'),(84,2093,1013,NULL,582108557,183,'user-runtime-dir@.service','user-runtime-dir@1000','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Runtime Directory /run/user/%i\nDocumentation=man:user@.service(5)\nAfter=systemd-logind.service dbus.service\nIgnoreOnIsolate=yes\n\n[Service]\nExecStart=/usr/lib/systemd/systemd-user-runtime-dir start %i\nExecStop=/usr/lib/systemd/systemd-user-runtime-dir stop %i\nType=oneshot\nRemainAfterExit=yes\nSlice=user-%i.slice\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:32','2026-10-17 13:50:32'),(85,2094,1013,NULL,582108557,184,'user@.service','user@1000','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Manager for UID %i\nDocumentation=man:user@.service(5)\nBindsTo=user-runtime-dir@%i.service\nAfter=systemd-logind.service user-runtime-dir@%i.service dbus.service systemd-oomd.service\nIgnoreOnIsolate=yes\n\n[Service]\nUser=%i\nPAMName=systemd-user\nType=notify-reload\nExecStart=/usr/lib/systemd/systemd --user\nSlice=user-%i.slice\n# Reexecute the manager on service reload, instead of reloading.\n# This provides a synchronous method for restarting all user manager\n# instances after upgrade.\nReloadSignal=RTMIN+25\nKillMode=mixed\nDelegate=pids memory cpu\nDelegateSubgroup=init.scope\nTasksMax=infinity\nTimeoutStopSec=120s\nKeyringMode=inherit\nOOMScoreAdjust=100\nMemoryPressureWatch=skip\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:32','2026-10-17 13:50:32'),(86,2095,1013,NULL,582108557,185,'wpa_supplicant.service','wpa_supplicant','[Unit]\nDescription=WPA supplicant\nBefore=network.target\nAfter=dbus.service\nWants=network.target\nIgnoreOnIsolate=true\n\n[Service]\nType=dbus\nBusName=fi.w1.wpa_supplicant1\nExecStart=/usr/sbin/wpa_supplicant -u -s -O \"DIR=/run/wpa_supplicant GROUP=netdev\"\nExecReload=/bin/kill -HUP $MAINPID\nGroup=netdev\nRuntimeDirectory=wpa_supplicant\nRuntimeDirectoryMode=0750\n\n[Install]\nWantedBy=multi-user.target\nAlias=dbus-fi.w1.wpa_supplicant1.service\n','abd9f14b966e14a3c1e2d2a8c16bc6178f60dae163214782b10d8eb3264af10f','v1','active','2026-10-17 13:50:33','2026-10-17 13:50:33'),(87,2096,1013,NULL,9396376846,186,'console-getty.service','console-getty','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Console Getty\nDocumentation=man:agetty(8) man:systemd-getty-generator(8)\nAfter=systemd-user-sessions.service plymouth-quit-wait.service getty-pre.target\nAfter=rc-local.service\nBefore=getty.target\n\n# OCI containers may be run without a console\nConditionPathExists=/dev/console\n\n[Service]\n# The \'-o\' option value tells agetty to replace \'login\' arguments with an option to preserve environment (-p),\n# followed by \'--\' for safety, and then the entered username.\nExecStart=-/sbin/agetty -o \'-p -- \\\\u\' --noclear --keep-baud - 115200,38400,9600 $TERM\nType=idle\nRestart=always\nUtmpIdentifier=cons\nStandardInput=tty\nStandardOutput=tty\nTTYPath=/dev/console\nTTYReset=yes\nTTYVHangup=yes\nIgnoreSIGPIPE=no\nSendSIGHUP=yes\nImportCredential=agetty.*\nImportCredential=login.*\n\n[Install]\nWantedBy=getty.target\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:35','2026-10-17 13:50:35'),(88,2097,1013,NULL,9396376846,187,'console-setup.service','console-setup','[Unit]\nDescription=Set console font and keymap\nDefaultDependencies=no\nAfter=console-screen.service kbd.service local-fs.target\nBefore=display-manager.service\nRequiresMountsFor=/usr\nConditionPathExists=/bin/setupcon\n\n[Service]\nType=oneshot\nExecStart=/lib/console-setup/console-setup.sh\nRemainAfterExit=yes\n\n[Install]\nWantedBy=multi-user.target\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:36','2026-10-17 13:50:36'),(89,2098,1013,NULL,9396376846,188,'cron.service','cron','[Unit]\nDescription=Regular background program processing daemon\nDocumentation=man:cron(8)\nAfter=remote-fs.target nss-user-lookup.target\n\n[Service]\nEnvironmentFile=-/etc/default/cron\nExecStart=/usr/sbin/cron -f -P $EXTRA_OPTS\nIgnoreSIGPIPE=false\nKillMode=process\nRestart=on-failure\nSyslogFacility=cron\n\n[Install]\nWantedBy=multi-user.target\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:36','2026-10-17 13:50:36'),(90,2099,1013,NULL,9396376846,189,'dbus.service','dbus','[Unit]\nDescription=D-Bus System Message Bus\nDocumentation=man:dbus-daemon(1)\nRequires=dbus.socket\n# Do not stop on shutdown\nDefaultDependencies=no\nWants=sysinit.target\nAfter=sysinit.target basic.target\n\n[Service]\nType=notify\nNotifyAccess=main\nExecStart=@/usr/bin/dbus-daemon @dbus-daemon --system --address=systemd: --nofork --nopidfile --systemd-activation --syslog-only\nExecReload=/usr/bin/dbus-send --print-reply --system --type=method_call --dest=org.freedesktop.DBus / org.freedesktop.DBus.ReloadConfig\nOOMScoreAdjust=-900\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:36','2026-10-17 13:50:36'),(91,2100,1013,NULL,9396376846,190,'getty@.service','getty@tty1','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Getty on %I\nDocumentation=man:agetty(8) man:systemd-getty-generator(8)\nDocumentation=https://0pointer.de/blog/projects/serial-console.html\nAfter=systemd-user-sessions.service plymouth-quit-wait.service getty-pre.target\nAfter=rc-local.service\n\n# If additional gettys are spawned during boot then we should make\n# sure that this is synchronized before getty.target, even though\n# getty.target didn\'t actually pull it in.\nBefore=getty.target\nIgnoreOnIsolate=yes\n\n# IgnoreOnIsolate causes issues with sulogin, if someone isolates\n# rescue.target or starts rescue.service from multi-user.target or\n# graphical.target.\nConflicts=rescue.service\nBefore=rescue.service\n\n# On systems without virtual consoles, don\'t start any getty. Note\n# that serial gettys are covered by serial-getty@.service, not this\n# unit.\nConditionPathExists=/dev/tty0\n\n[Service]\n# the VT is cleared by TTYVTDisallocate\n# The \'-o\' option value tells agetty to replace \'login\' arguments with an\n# option to preserve environment (-p), followed by \'--\' for safety, and then\n# the entered username.\nExecStart=-/sbin/agetty -o \'-p -- \\\\u\' --noclear - $TERM\nType=idle\nRestart=always\nRestartSec=0\nUtmpIdentifier=%I\nStandardInput=tty\nStandardOutput=tty\nTTYPath=/dev/%I\nTTYReset=yes\nTTYVHangup=yes\nTTYVTDisallocate=yes\nIgnoreSIGPIPE=no\nSendSIGHUP=yes\nImportCredential=agetty.*\nImportCredential=login.*\n\n# Unset locale for the console getty since the console has problems\n# displaying some internationalized messages.\nUnsetEnvironment=LANG LANGUAGE LC_CTYPE LC_NUMERIC LC_TIME LC_COLLATE LC_MONETARY LC_MESSAGES LC_PAPER LC_NAME LC_ADDRESS LC_TELEPHONE LC_MEASUREMENT LC_IDENTIFICATION\n\n[Install]\nWantedBy=getty.target\nDefaultInstance=tty1\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:36','2026-10-17 13:50:36'),(92,2101,1013,NULL,9396376846,191,'keyboard-setup.service','keyboard-setup','[Unit]\nDescription=Set the console keyboard layout\nDefaultDependencies=no\nBefore=local-fs-pre.target\nWants=local-fs-pre.target\nConditionPathExists=/bin/setupcon\n\n[Service]\nType=oneshot\nExecStart=/lib/console-setup/keyboard-setup.sh\nRemainAfterExit=yes\n\n[Install]\nWantedBy=sysinit.target\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:36','2026-10-17 13:50:36'),(93,2102,1013,NULL,9396376846,192,'kmod-static-nodes.service','kmod-static-nodes','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create List of Static Device Nodes\nDefaultDependencies=no\nBefore=sysinit.target systemd-tmpfiles-setup-dev-early.service\nConditionCapability=CAP_SYS_MODULE\nConditionFileNotEmpty=/lib/modules/%v/modules.devname\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/bin/kmod static-nodes --format=tmpfiles --output=/run/tmpfiles.d/static-nodes.conf\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:37','2026-10-17 13:50:37'),(94,2103,1013,NULL,9396376846,193,'polkit.service','polkit','[Unit]\nDescription=Authorization Manager\nDocumentation=man:polkit(8)\n\n[Service]\nType=dbus\nBusName=org.freedesktop.PolicyKit1\nCapabilityBoundingSet=CAP_SETUID CAP_SETGID\nDeviceAllow=/dev/null rw\nDevicePolicy=strict\nExecStart=/usr/lib/polkit-1/polkitd --no-debug\nUser=polkitd\nLimitMEMLOCK=0\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateDevices=yes\nPrivateTmp=yes\nProtectControlGroups=yes\nProtectHome=yes\nProtectKernelModules=yes\nProtectKernelLogs=yes\nProtectKernelTunables=yes\nProtectSystem=strict\nProtectClock=yes\nProtectHostname=yes\nRemoveIPC=yes\nRestrictAddressFamilies=AF_UNIX\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nSystemCallArchitectures=native\nSystemCallFilter=@system-service\nUMask=0077\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:37','2026-10-17 13:50:37'),(95,2104,1013,NULL,9396376846,194,'rsyslog.service','rsyslog','[Unit]\nDescription=System Logging Service\nRequires=syslog.socket\nDocumentation=man:rsyslogd(8)\nDocumentation=man:rsyslog.conf(5)\nDocumentation=https://www.rsyslog.com/doc/\n\n[Service]\nType=notify\nExecStartPre=/usr/lib/rsyslog/reload-apparmor-profile\nExecStart=/usr/sbin/rsyslogd -n -iNONE\nStandardOutput=null\nStandardError=journal\nRestart=on-failure\n\n# Increase the default a bit in order to allow many simultaneous\n# files to be monitored, we might need a lot of fds.\nLimitNOFILE=16384\n\nCapabilityBoundingSet=CAP_BLOCK_SUSPEND CAP_CHOWN CAP_DAC_OVERRIDE CAP_LEASE CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_SYS_ADMIN CAP_SYS_RESOURCE CAP_SYSLOG CAP_MAC_ADMIN CAP_SETGID CAP_SETUID\nSystemCallFilter=@system-service\nRestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX\nNoNewPrivileges=yes\nProtectHome=no\nProtectClock=yes\nProtectHostname=yes\n\n[Install]\nWantedBy=multi-user.target\nAlias=syslog.service\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:37','2026-10-17 13:50:37'),(96,2105,1013,NULL,9396376846,195,'setvtrgb.service','setvtrgb','[Unit]\nDescription=Set console scheme\nDefaultDependencies=no\nAfter=systemd-user-sessions.service plymouth-quit-wait.service\nBefore=system-getty.slice\nConditionPathExists=/sbin/setvtrgb\nConditionPathExists=/dev/tty0\n\n[Service]\nType=oneshot\nExecStart=/sbin/setvtrgb /etc/vtrgb\nRemainAfterExit=yes\n\n[Install]\nWantedBy=sysinit.target\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:37','2026-10-17 13:50:37'),(97,2106,1013,NULL,9396376846,196,'snapd.seeded.service','snapd.seeded','[Unit]\nDescription=Wait until snapd is fully seeded\nAfter=snapd.socket\nRequires=snapd.socket\n\n[Service]\nType=oneshot\nExecStart=/usr/bin/snap wait system seed.loaded\nRemainAfterExit=true\n\n[Install]\nWantedBy=multi-user.target cloud-final.service\n# This is handled special in snapd\n# X-Snapd-Snap: do-not-start\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:37','2026-10-17 13:50:37'),(98,2107,1013,NULL,9396376846,197,'systemd-binfmt.service','systemd-binfmt','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Set Up Additional Binary Formats\nDocumentation=man:systemd-binfmt.service(8) man:binfmt.d(5)\nDocumentation=https://docs.kernel.org/admin-guide/binfmt-misc.html\nDocumentation=https://www.freedesktop.org/wiki/Software/systemd/APIFileSystems\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=proc-sys-fs-binfmt_misc.automount\nAfter=proc-sys-fs-binfmt_misc.mount\nAfter=local-fs.target\nBefore=sysinit.target shutdown.target\nConditionPathIsMountPoint=/proc/sys/fs/binfmt_misc\nConditionDirectoryNotEmpty=|/lib/binfmt.d\nConditionDirectoryNotEmpty=|/usr/lib/binfmt.d\nConditionDirectoryNotEmpty=|/usr/local/lib/binfmt.d\nConditionDirectoryNotEmpty=|/etc/binfmt.d\nConditionDirectoryNotEmpty=|/run/binfmt.d\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-binfmt\nExecStop=/usr/lib/systemd/systemd-binfmt --unregister\nTimeoutSec=90s\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:38','2026-10-17 13:50:38'),(99,2108,1013,NULL,9396376846,198,'systemd-journal-flush.service','systemd-journal-flush','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Flush Journal to Persistent Storage\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\n\nConditionPathExists=!/etc/initrd-release\n\nDefaultDependencies=no\nAfter=systemd-remount-fs.service\nBefore=systemd-tmpfiles-setup.service\nWants=systemd-journald.service\nAfter=systemd-journald.service\nRequiresMountsFor=/var/log/journal\n\n[Service]\nExecStart=journalctl --flush\nExecStop=journalctl --smart-relinquish-var\nType=oneshot\nRemainAfterExit=yes\nTimeoutSec=90s\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:38','2026-10-17 13:50:38'),(100,2109,1013,NULL,9396376846,199,'systemd-journald.service','systemd-journald','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Journal Service\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\nDefaultDependencies=no\nRequires=systemd-journald.socket\nAfter=systemd-journald.socket systemd-journald-dev-log.socket systemd-journald-audit.socket syslog.socket\nBefore=sysinit.target\n\n# To avoid journald SIGKILLed during soft-reboot and corrupting journals.\n# See https://github.com/systemd/systemd/issues/30195\nBefore=soft-reboot.target\nConflicts=soft-reboot.target\n\n# Mount and swap units need the journal socket units. If they were removed by\n# an isolate request the mount and swap units would be removed too, hence let\'s\n# exclude systemd-journald and its sockets from isolate requests.\nIgnoreOnIsolate=yes\n\n[Service]\nDeviceAllow=char-* rw\nExecStart=/usr/lib/systemd/systemd-journald\nFileDescriptorStoreMax=4224\nIPAddressDeny=any\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nOOMScoreAdjust=-250\nProtectClock=yes\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/journal\nRuntimeDirectoryPreserve=yes\n# Audit socket is not listed here because this unit can be turned off. However\n# the link between the socket and the service units is still created thanks to\n# the \'Service=\' setting specified in the socket unit.\nSockets=systemd-journald.socket systemd-journald-dev-log.socket\nStandardOutput=null\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nType=notify\nPassEnvironment=TERM\nWatchdogSec=3min\n\n# In case you\'re wondering why CAP_SYS_PTRACE is needed, access to\n# /proc/<pid>/exe requires this capability. Thus if this capability is missing\n# the _EXE=/OBJECT_EXE= fields will be missing from the journal entries.\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_DAC_OVERRIDE CAP_SYS_PTRACE CAP_SYSLOG CAP_AUDIT_CONTROL CAP_AUDIT_READ CAP_CHOWN CAP_DAC_READ_SEARCH CAP_FOWNER CAP_SETUID CAP_SETGID CAP_MAC_OVERRIDE\n\n# If there are many split up journal files we need a lot of fds to access them\n# all in parallel.\nLimitNOFILE=524288\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:38','2026-10-17 13:50:38'),(101,2110,1013,NULL,9396376846,200,'systemd-logind.service','systemd-logind','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Login Management\nDocumentation=man:sd-login(3)\nDocumentation=man:systemd-logind.service(8)\nDocumentation=man:logind.conf(5)\nDocumentation=man:org.freedesktop.login1(5)\n\nWants=user.slice modprobe@drm.service\nAfter=nss-user-lookup.target user.slice modprobe@drm.service\n\n# Ask for the dbus socket.\nWants=dbus.socket\nAfter=dbus.socket\n\n[Service]\nBusName=org.freedesktop.login1\nCapabilityBoundingSet=CAP_SYS_ADMIN CAP_MAC_ADMIN CAP_AUDIT_CONTROL CAP_CHOWN CAP_DAC_READ_SEARCH CAP_DAC_OVERRIDE CAP_FOWNER CAP_SYS_TTY_CONFIG CAP_LINUX_IMMUTABLE\nDeviceAllow=block-* r\nDeviceAllow=char-/dev/console rw\nDeviceAllow=char-drm rw\nDeviceAllow=char-input rw\nDeviceAllow=char-tty rw\nDeviceAllow=char-vcs rw\nExecStart=/usr/lib/systemd/systemd-logind\nFileDescriptorStoreMax=512\nIPAddressDeny=any\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateTmp=yes\n# We don\'t use ProtectProc= since we need to look for usernames and tty for wall messages\nProtectClock=yes\nProtectControlGroups=yes\nProtectHome=yes\nProtectHostname=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectSystem=strict\nReadWritePaths=/etc /run\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/sessions systemd/seats systemd/users systemd/inhibit systemd/shutdown\nRuntimeDirectoryPreserve=yes\nStateDirectory=systemd/linger\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nType=notify-reload\nWatchdogSec=3min\n\n# Increase the default a bit in order to allow many simultaneous logins since\n# we keep one fd open per session.\nLimitNOFILE=524288\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:38','2026-10-17 13:50:38'),(102,2111,1013,NULL,9396376846,201,'systemd-modules-load.service','systemd-modules-load','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Load Kernel Modules\nDocumentation=man:systemd-modules-load.service(8) man:modules-load.d(5)\nDefaultDependencies=no\nConflicts=shutdown.target\nBefore=sysinit.target shutdown.target\nConditionCapability=CAP_SYS_MODULE\nConditionDirectoryNotEmpty=|/lib/modules-load.d\nConditionDirectoryNotEmpty=|/usr/lib/modules-load.d\nConditionDirectoryNotEmpty=|/usr/local/lib/modules-load.d\nConditionDirectoryNotEmpty=|/etc/modules-load.d\nConditionDirectoryNotEmpty=|/run/modules-load.d\nConditionKernelCommandLine=|modules-load\nConditionKernelCommandLine=|rd.modules-load\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-modules-load\nTimeoutSec=90s\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:38','2026-10-17 13:50:38'),(103,2112,1013,NULL,9396376846,202,'systemd-remount-fs.service','systemd-remount-fs','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Remount Root and Kernel File Systems\nDocumentation=man:systemd-remount-fs.service(8)\nDocumentation=https://www.freedesktop.org/wiki/Software/systemd/APIFileSystems\n\nDefaultDependencies=no\nAfter=systemd-fsck-root.service\nBefore=local-fs-pre.target local-fs.target\nWants=local-fs-pre.target\nConflicts=shutdown.target\nBefore=shutdown.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-remount-fs\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:39','2026-10-17 13:50:39'),(104,2113,1013,NULL,9396376846,203,'systemd-resolved.service','systemd-resolved','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Network Name Resolution\nDocumentation=man:systemd-resolved.service(8)\nDocumentation=man:org.freedesktop.resolve1(5)\nDocumentation=https://www.freedesktop.org/wiki/Software/systemd/writing-network-configuration-managers\nDocumentation=https://www.freedesktop.org/wiki/Software/systemd/writing-resolver-clients\n\nDefaultDependencies=no\nAfter=systemd-sysctl.service systemd-sysusers.service\nBefore=sysinit.target network.target nss-lookup.target shutdown.target initrd-switch-root.target\nConflicts=shutdown.target initrd-switch-root.target\nWants=nss-lookup.target\n\n[Service]\nAmbientCapabilities=CAP_SETPCAP CAP_NET_RAW CAP_NET_BIND_SERVICE\nBusName=org.freedesktop.resolve1\nCapabilityBoundingSet=CAP_SETPCAP CAP_NET_RAW CAP_NET_BIND_SERVICE\nExecStart=!!/usr/lib/systemd/systemd-resolved\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateDevices=yes\nPrivateTmp=yes\nProtectClock=yes\nProtectControlGroups=yes\nProtectHome=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectKernelTunables=yes\nProtectSystem=strict\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_NETLINK AF_INET AF_INET6\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/resolve\nRuntimeDirectoryPreserve=yes\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service\nType=notify\nUser=systemd-resolve\nImportCredential=network.dns\nImportCredential=network.search_domains\nWatchdogSec=3min\n\n[Install]\nWantedBy=sysinit.target\nAlias=dbus-org.freedesktop.resolve1.service\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:39','2026-10-17 13:50:39'),(105,2114,1013,NULL,9396376846,204,'systemd-sysctl.service','systemd-sysctl','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Apply Kernel Variables\nDocumentation=man:systemd-sysctl.service(8) man:sysctl.d(5)\nDefaultDependencies=no\nConflicts=shutdown.target\nAfter=systemd-modules-load.service\nBefore=sysinit.target shutdown.target\nConditionPathIsReadWrite=/proc/sys/net/\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-sysctl\nTimeoutSec=90s\nImportCredential=sysctl.*\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:39','2026-10-17 13:50:39'),(106,2115,1013,NULL,9396376846,205,'systemd-timesyncd.service','systemd-timesyncd','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Network Time Synchronization\nDocumentation=man:systemd-timesyncd.service(8)\nConditionCapability=CAP_SYS_TIME\nConditionVirtualization=!container\nDefaultDependencies=no\nAfter=systemd-sysusers.service\nBefore=time-set.target sysinit.target shutdown.target\nConflicts=shutdown.target\nWants=time-set.target\n\n[Service]\nAmbientCapabilities=CAP_SYS_TIME\nBusName=org.freedesktop.timesync1\nCapabilityBoundingSet=CAP_SYS_TIME\n# Turn off DNSSEC validation for hostname look-ups, since those need the\n# correct time to work, but we likely won\'t acquire that without NTP. Let\'s\n# break this chicken-and-egg cycle here.\nEnvironment=SYSTEMD_NSS_RESOLVE_VALIDATE=0\nExecStart=!!/usr/lib/systemd/systemd-timesyncd\nLockPersonality=yes\nMemoryDenyWriteExecute=yes\nNoNewPrivileges=yes\nPrivateDevices=yes\nPrivateTmp=yes\nProtectProc=invisible\nProtectControlGroups=yes\nProtectHome=yes\nProtectHostname=yes\nProtectKernelLogs=yes\nProtectKernelModules=yes\nProtectKernelTunables=yes\nProtectSystem=strict\nRestart=always\nRestartSec=0\nRestrictAddressFamilies=AF_UNIX AF_INET AF_INET6\nRestrictNamespaces=yes\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nRuntimeDirectory=systemd/timesync\nStateDirectory=systemd/timesync\nSystemCallArchitectures=native\nSystemCallErrorNumber=EPERM\nSystemCallFilter=@system-service @clock\nType=notify\nUser=systemd-timesync\nWatchdogSec=3min\n\n[Install]\nWantedBy=sysinit.target\nAlias=dbus-org.freedesktop.timesync1.service\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:39','2026-10-17 13:50:39'),(107,2116,1013,NULL,9396376846,206,'systemd-tmpfiles-setup-dev-early.service','systemd-tmpfiles-setup-dev-early','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create Static Device Nodes in /dev gracefully\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nBefore=sysinit.target local-fs-pre.target systemd-udevd.service\nWants=local-fs-pre.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --prefix=/dev --create --boot --graceful\nSuccessExitStatus=DATAERR CANTCREAT\nImportCredential=tmpfiles.*\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:39','2026-10-17 13:50:39'),(108,2117,1013,NULL,9396376846,207,'systemd-tmpfiles-setup-dev.service','systemd-tmpfiles-setup-dev','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create Static Device Nodes in /dev\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nAfter=systemd-tmpfiles-setup-dev-early.service\nBefore=sysinit.target local-fs-pre.target systemd-udevd.service\nWants=local-fs-pre.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --prefix=/dev --create --boot\nSuccessExitStatus=DATAERR CANTCREAT\nImportCredential=tmpfiles.*\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:40','2026-10-17 13:50:40'),(109,2118,1013,NULL,9396376846,208,'systemd-tmpfiles-setup.service','systemd-tmpfiles-setup','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Create Volatile Files and Directories\nDocumentation=man:tmpfiles.d(5) man:systemd-tmpfiles(8)\n\nDefaultDependencies=no\nAfter=local-fs.target systemd-sysusers.service systemd-journald.service\nBefore=sysinit.target\nConflicts=shutdown.target initrd-switch-root.target\nBefore=shutdown.target initrd-switch-root.target\nRefuseManualStop=yes\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=systemd-tmpfiles --create --remove --boot --exclude-prefix=/dev\nSuccessExitStatus=DATAERR CANTCREAT\nImportCredential=tmpfiles.*\nImportCredential=login.motd\nImportCredential=login.issue\nImportCredential=network.hosts\nImportCredential=ssh.authorized_keys.root\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:40','2026-10-17 13:50:40'),(110,2119,1013,NULL,9396376846,209,'systemd-udev-trigger.service','systemd-udev-trigger','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Coldplug All udev Devices\nDocumentation=man:udev(7) man:systemd-udevd.service(8)\nDefaultDependencies=no\nWants=systemd-udevd.service\nAfter=systemd-udevd-kernel.socket systemd-udevd-control.socket\nBefore=sysinit.target\nConditionPathIsReadWrite=/sys\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=-udevadm trigger --type=all --action=add --prioritized-subsystem=module,block,tpmrm,net,tty,input\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:40','2026-10-17 13:50:40'),(111,2120,1013,NULL,9396376846,210,'systemd-udevd.service','systemd-udevd','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Rule-based Manager for Device Events and Files\nDocumentation=man:systemd-udevd.service(8) man:udev(7)\nDefaultDependencies=no\nAfter=systemd-sysusers.service systemd-hwdb-update.service\nBefore=sysinit.target\nConditionPathIsReadWrite=/sys\n\n[Service]\nCapabilityBoundingSet=~CAP_SYS_TIME CAP_WAKE_ALARM\nDelegate=pids\nDelegateSubgroup=udev\nType=notify-reload\n# Note that udev will reset the value internally for its workers\nOOMScoreAdjust=-1000\nSockets=systemd-udevd-control.socket systemd-udevd-kernel.socket\nRestart=always\nRestartSec=0\nExecStart=/usr/lib/systemd/systemd-udevd\nKillMode=mixed\nTasksMax=infinity\nPrivateMounts=yes\nProtectHostname=yes\nMemoryDenyWriteExecute=yes\nRestrictAddressFamilies=AF_UNIX AF_NETLINK AF_INET AF_INET6\nRestrictRealtime=yes\nRestrictSUIDSGID=yes\nSystemCallFilter=@system-service @module @raw-io bpf\nSystemCallFilter=~@clock\nSystemCallErrorNumber=EPERM\nSystemCallArchitectures=native\nLockPersonality=yes\nIPAddressDeny=any\nWatchdogSec=3min\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:40','2026-10-17 13:50:40'),(112,2121,1013,NULL,9396376846,211,'systemd-update-utmp.service','systemd-update-utmp','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Record System Boot/Shutdown in UTMP\nDocumentation=man:systemd-update-utmp.service(8) man:utmp(5)\nConditionPathExists=!/etc/initrd-release\n\nDefaultDependencies=no\nAfter=systemd-remount-fs.service systemd-tmpfiles-setup.service auditd.service\nBefore=sysinit.target\nConflicts=shutdown.target\nBefore=shutdown.target\nRequiresMountsFor=/var/log/wtmp\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-update-utmp reboot\nExecStop=/usr/lib/systemd/systemd-update-utmp shutdown\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:40','2026-10-17 13:50:40'),(113,2122,1013,NULL,9396376846,212,'systemd-user-sessions.service','systemd-user-sessions','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=Permit User Sessions\nDocumentation=man:systemd-user-sessions.service(8)\nAfter=remote-fs.target nss-user-lookup.target network.target home.mount\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/lib/systemd/systemd-user-sessions start\nExecStop=/usr/lib/systemd/systemd-user-sessions stop\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:41','2026-10-17 13:50:41'),(114,2123,1013,NULL,9396376846,213,'unattended-upgrades.service','unattended-upgrades','[Unit]\nDescription=Unattended Upgrades Shutdown\nAfter=network.target local-fs.target systemd-logind.service\nRequiresMountsFor=/run /var/log /var/run /var/lib /boot\nDocumentation=man:unattended-upgrade(8)\n\n[Service]\nExecStart=/usr/share/unattended-upgrades/unattended-upgrade-shutdown --wait-for-signal\nKillMode=process\nTimeoutStopSec=1800\n\n[Install]\nWantedBy=multi-user.target\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-10-17 13:50:41','2026-10-17 13:50:41'),(115,2124,1013,NULL,9396376846,214,'user-runtime-dir@.service','user-runtime-dir@0','#  SPDX-License-Identifier: LGPL-2.1-or-later\n#\n#  This file is part of systemd.\n#\n#  systemd is free software; you can redistribute it and/or modify it\n#  under the terms of the GNU Lesser General Public License as published by\n#  the Free Software Foundation; either version 2.1 of the License, or\n#  (at your option) any later version.\n\n[Unit]\nDescription=User Runtime Directory /run/user/%i\nDocumentation=man:user@.service(5)\nAfter=dbus.service\nStopWhenUnneeded=yes\nIgnoreOnIsolate=yes\n\n[Service]\nExecStart=/usr/lib/systemd/systemd-user-runtime-dir start %i\nExecStop=/usr/lib/systemd/systemd-user-runtime-dir stop %i\nType=oneshot\nRemainAfterExit=yes\nSlice=user-%i.slice\n','c22a96ec79ce24f37f5469b08c76aab6c32d4031f49522b12da3ac621224d4c9','v1','active','2026-